(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-fa3-blackwell-attn"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-1\">一 · 一次分辨率上调引发的采样雪崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-2\">二 · 它到底解决哪一个问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-3\">三 · 机制：数据流顺序决定收益从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-4\">四 · 代价账：延迟、吞吐、显存、带宽各让出什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-5\">五 · 适用边界的三个硬条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-6\">六 · 先看一次“分辨率一升就崩”的线上事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-7\">七 · 失效条件：三类边界必须提前判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-8\">八 · 边界不在“能不能跑”，而在“哪一步先崩”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-9\">九 · Q tile 切分与 TMA 预取：把请求变成可流水的 tile 序列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-10\">十 · QK^T 走 FP8 tcgen05 MMA：GEMM 与 softmax 的角色分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-11\">十一 · 寄存器内 online softmax：跨 tile 递推的状态机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-12\">十二 · PV GEMM 与下一 tile 的 QK^T 重叠：FP16 精度的守门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-13\">十三 · 归一化收尾与写回：直接喂给下一层 LayerNorm</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-14\">十四 · 步骤间的耦合代价：形状、缓冲深度与缩放因子的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-15\">十五 · 流水线的断点：TMA 双缓冲、FP8 缩放与对齐约束如何吃掉收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-16\">十六 · 异步 FA3 的边界：流水何时失效、代价落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-17\">十七 · 从三重求和到分块递推：公式逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-18\">十八 · 精度分工的推导：为什么 FP8 只给 QK^T</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-19\">十九 · 伪代码：把流水落到可实现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-20\">二十 · 形状约束的代价分析</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-21\">二十一 · 与相邻实现的边界：一句话指路后的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-22\">二十二 · 异步 FA3 在 DiT 上的失效边界：从 online softmax 递推到 shared memory 容量墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-23\">二十三 · 异步 FA3 的收益边界与失效面：从 online softmax 递推到流水深度约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-24\">二十四 · 请求形态：序列长度是配方的第一变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-25\">二十五 · 长度分布：批内方差比均值更致命</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-26\">二十六 · 并发与批大小：occupancy 与 shared memory 的拉扯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-27\">二十七 · 负载不对时的三种退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-28\">二十八 · 配方核对清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-29\">二十九 · 负载配方与失效边界：异步 FA3 在什么请求形态下才划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-30\">三十 · 硬件档位：把 SM100 的异步通路吃满，而不是把卡堆多</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-31\">三十一 · 并行拓扑：序列切分优先于张量切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-32\">三十二 · 量化方案：FP8 只给 QK^T，PV 守 FP16，per-head scaling 是开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-33\">三十三 · KV 策略：双缓冲深度决定收益上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-34\">三十四 · 调度参数：按 tile 粒度而不是按请求粒度排队</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-35\">三十五 · 可复现的配置思路：从对齐检查倒推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-36\">三十六 · 这套配方的边界：对齐约束、双缓冲深度与画质退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-37\">三十七 · 显存与驻留：双缓冲深度决定收益上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-38\">三十八 · 带宽：O(N²) 到 O(N·d) 之后，瓶颈换了位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-39\">三十九 · 通信：并行切分与 KV 搬运的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-40\">四十 · 功耗与时钟：FP8 省下的不只是时间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-41\">四十一 · 尾延迟：均值好看，P99 崩在合并点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-42\">四十二 · 规模上去先崩在哪：按序列长度分段的判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-43\">四十三 · 规模上去以后，先崩的是 shared memory 与流水深度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-44\">四十四 · 规模上去以后，先崩的是 shared memory 而不是 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-45\">四十五 · 精度退化：FP8 QK^T 的溢出路径与可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-46\">四十六 · 形状不匹配：非 64/128 对齐的静默回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-47\">四十七 · OOM 与批抖动：双缓冲深度与 KV 驻留的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-48\">四十八 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-49\">四十九 · 监控分层与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-50\">五十 · 失效边界：从数值溢出到流水塌陷的四种可观测病灶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-51\">五十一 · 同族谱系：异步 FA3 在注意力实现树上的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-52\">五十二 · 与 FlashAttention-2 的分界：异步通路是否被真正用起来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-53\">五十三 · 与近似替代分支的分界：削减 N 还是优化 IO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-54\">五十四 · 与精度分层族的分界：FP8 注意力 vs 全链量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-55\">五十五 · 决策表：按序列长度、形状对齐与 SLO 三轴选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-56\">五十六 · 适用条件的硬边界与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fa3-blackwell-attn-sec-57\">五十七 · 边界在哪：与 FA2、朴素分块、PagedAttention 的选型对照</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按序列切 Q tile，KV 以 TMA 异步预取到 shared mem…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">QK^T 走 FP8 tcgen05 MMA，softmax 在寄存器内做…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">softmax 结果转 FP16 与 V tile 做 PV GEMM，与…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按 online softmax 递推合并跨 tile 的部分和，最后统一…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出写回 HBM 并直接喂给下一层 DiT block 的 LayerNo…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-fa3-blackwell-attn-sec-1\">一 · 一次分辨率上调引发的采样雪崩</h3>\n<p>某条已经上线的图像生成服务，采样配置长期停在 768²，DiT block 里的全局注意力序列长度还在几千的量级，端到端延迟稳定在 SLO 预算之内。产品侧把出图分辨率抬到 1024² 之后，序列长度跨过 4k 门槛，再叠加高分辨率档位下的 16k 序列请求，线上出现了典型的非线性劣化：单步采样时延不是按比例增长，而是成倍跳升；GPU 的 SM 利用率反而掉下去，HBM 带宽读数顶到墙；同一张卡上原本能并行的批被迫缩小，连续批处理队列开始堆积，尾延迟击穿 SLO。运维侧第一反应是加卡，但加卡只把排队时间摊薄，单请求的时延曲线没有变。</p>\n<p>把 profile 拉出来看，瓶颈不在 GEMM 的算力上，而在朴素 attention 的数据搬运上。它每算一个 Q tile 就要把整段 K、V 从 HBM 重新读一遍，读写量随序列长度平方增长，而 SM 在等数据。用公式刻画就是：</p>\n<div class=\"formula\">$$O_{i}=\\sum_{j}\\frac{\\exp(q_{i}k_{j}^{\\top}/\\sqrt{d}-m_{i})}{\\ell_{i}}v_{j},\\quad \\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}},\\ \\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</div>\n<p>式子里 $N$ 是序列长度、$d$ 是 head_dim。当 $N$ 从几千涨到 16k，$N^2 d$ 这一项的增速远超算力增速，于是系统从 SM bound 滑向 HBM bound，加速比的上界就是这两个 bound 的比值。更麻烦的是 KV 无法驻留：16k 序列的 KV 体量已经超出单卡可常驻的范围，只能反复回读，SM 利用率被拖到低位。这次事故的本质不是“模型变慢了”，而是 attention 的访存模式在长序列下失效。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-2\">二 · 它到底解决哪一个问题</h3>\n<p>本算法对准的问题域非常窄：DiT 的全局注意力，在 1024² 以上分辨率、序列长度 4k–16k 的采样请求上，把 HBM 读写从主瓶颈位置上挪开。它要的是三件事同时成立——KV tile 驻留片上、QK^T 与 softmax 及 PV 三段计算互相重叠、跨 tile 的部分和能在不落盘的前提下正确合并。判断一个请求是否落在这个问题域里，看两个量：序列长度是否已经让 $N^2 d$ 压过算力项，以及 KV 是否已经无法整段驻留。两条都成立，才轮到这套 kernel 出场。</p>\n<p>它不解决的问题同样要划清。第一，它不改善单 token 的 GEMM 效率，MLP 与投影层的算力瓶颈原样保留，端到端时延里那部分不会被这套 attention 吃掉。第二，它不解决跨卡并行与通信，序列再长也不会自动切分到多卡，NVLink 域内的 all-to-all 与 KV 传输是别的层的事。第三，它不解决调度层的批拼装与优先级，连续批处理怎么组批、SLO 怎么分配预算，与本 kernel 无关。第四，它不负责量化校准策略本身，per-head scaling 的系数怎么定是校准环节的产物，kernel 只消费它。把这条边界记住，才不会在 MLP bound 的场景里误判收益。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-3\">三 · 机制：数据流顺序决定收益从哪来</h3>\n<p>收益来自三段计算被排进同一条 warp-specialized 生产者/消费者流水。按数据流走一遍：先按序列切 Q tile，KV 由 TMA 异步预取到 shared memory 的双缓冲里，生产者在搬运、消费者在计算，两条 warp 组各司其职；QK^T 走 FP8 的 tcgen05 MMA，把矩阵乘压进 Tensor Core；softmax 在寄存器内做 online 归一化，结果写回 FP32 累加器；softmax 输出转成 FP16 后与 V tile 做 PV GEMM，并且这一步与下一个 KV tile 的 QK^T 重叠。跨 tile 的合并靠 online softmax 递推：</p>\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n<p>这里 $m$ 是 running max、$\\ell$ 是归一化因子，每个 tile 只保留部分和与这两个标量，最后统一除以归一化因子得到输出。关键点在于：整个过程中间结果从不写回 HBM，输出只在最后落一次，并且直接喂给下一层 DiT block 的 LayerNorm。访存模式因此从 O(N²) 降到 O(N·d)，这是 16k 序列下时延能降 2–4 倍的根本原因，而不是靠更快的 MMA 单独撑起来的。</p>\n<p>精度分工是这套机制的另一半。QK^T 用 FP8 在 Blackwell 上吞吐翻倍，但 PV 保持 FP16 高精度，使画质几乎无损。这个非对称选择有明确的工程理由：attention logit 的动态范围决定 softmax 的锐度，FP8 在 QK^T 上省的是带宽与算力，而 PV 的累加直接决定像素值，降精度会立刻反映在画质上。代价是 FP8 QK^T 对 logit 动态范围敏感，必须 per-head scaling，否则高分辨率细节糊化，且这种退化无法靠后处理挽回。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-4\">四 · 代价账：延迟、吞吐、显存、带宽各让出什么</h3>\n<p>延迟侧，收益随序列长度增长而非线性。4k 附近序列还没完全压过算力项，收益有限；到 16k 才拿到 2–4 倍。这意味着不能把 16k 的加速比外推到所有档位，容量规划要按请求的序列长度分布分段估算。</p>\n<p>吞吐侧，FP8 QK^T 让 Tensor Core 的有效吞吐翻倍，但整卡吞吐还受 PV 的 FP16 GEMM 与 softmax 的寄存器压力牵制，所以吞吐提升幅度低于 QK^T 单项的翻倍。批大小与 SLO 的具体数值未给出，工程上应按分段延迟曲线反推可并行的批上限，而不是按峰值吞吐倒推。</p>\n<p>显存与带宽侧，KV tile 驻留 shared memory 双缓冲，规模上限直接受 shared memory 容量与双缓冲深度约束。双缓冲深度不足时，TMA 预取与 MMA 无法重叠，HBM 流量回落，16k 序列的时延收益被吃掉——这是最隐蔽的一类回退，profile 上表现为带宽读数回升而 SM 利用率不升。功耗侧，异步流水把 SM 与搬运单元同时拉满，单位时间能耗上升，但总能耗因时延缩短而下降，账要按每张图算而不是按每秒算。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>朴素 attention</th><th>本算法</th><th>约束条件</th></tr></thead><tbody><tr><td>HBM 流量</td><td>O(N²)</td><td>O(N·d)</td><td>KV tile 全程驻留片上</td></tr><tr><td>SM 利用率</td><td>低，等数据</td><td>高，三段重叠</td><td>双缓冲深度足够</td></tr><tr><td>QK^T 精度</td><td>FP16</td><td>FP8 + per-head scaling</td><td>校准系数必须到位</td></tr><tr><td>PV 精度</td><td>FP16</td><td>FP16</td><td>不降精度以保画质</td></tr><tr><td>形状适配</td><td>任意</td><td>head_dim/tile 需 64/128 对齐</td><td>非对齐变体需重写 kernel</td></tr></tbody></table>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-5\">五 · 适用边界的三个硬条件</h3>\n<p>第一个硬条件是形状对齐。warp-specialized 流水对 head_dim 与 tile 形状挑剔，非 64/128 对齐的 DiT 变体直接套用 kernel 会触发重写或性能回退，流水无法按预期重叠。工程判断很直接：模型结构定型前就把 head_dim 锁到 64 或 128 的整数倍，比事后改 kernel 便宜得多。</p>\n<p>第二个硬条件是 per-head scaling 的校准链路。FP8 QK^T 缺少 per-head scaling 时，attention logit 动态范围溢出会导致高分辨率细节糊化，画质退化难以通过后处理挽回。这条不是可选优化，而是正确性前提；校准系数要按 head 粒度产出并随模型版本一起发布，任何绕过校准直接开 FP8 的路径都应视为不可上线。</p>\n<p>第三个硬条件是双缓冲深度与 shared memory 预算的匹配。深度不足则预取与 MMA 无法重叠，收益归零；深度过大则挤占其他阶段的片上空间，反而限制 tile 尺寸。规模上限由此确定：序列长度不是可以无限外推的，超过 shared memory 能容纳的 KV tile 与双缓冲组合之后，这套 kernel 的收益曲线会掉头。与相邻算法的差别也要放在这条边界里看——它把 HBM 流量从 O(N²) 降到 O(N·d)，而 FlashAttention-2 的流水未针对 Blackwell 异步通路，所以在 Blackwell 上拿不到同等重叠度；FP8 只用于 QK^T、PV 保持 FP16，是这套方案在画质与吞吐之间划出的那条线。</p>\n<p>落到工程判断上：先量请求的序列长度分布，确认 4k–16k 段占比是否足以摊平重写 kernel 的成本；再核对 head_dim 与 tile 的 64/128 对齐情况；最后把 per-head scaling 的校准与双缓冲深度一起纳入发布检查单。三条任一不满足，这套 attention 的收益就不是 2–4 倍，而是回退。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-6\">六 · 先看一次“分辨率一升就崩”的线上事故</h3>\n<p>某条文生图服务的采样链路在 1024² 分辨率下跑得很稳，运维把分辨率档位放开到 2K 之后，同一套 DiT 采样在高峰期出现整批超时：单次采样时延从可接受区间直接跳到数倍，GPU 的 SM 占用率反而掉下来，HBM 带宽读数顶到天花板。根因不是模型变大，而是全局注意力的序列长度随分辨率平方增长，跨进了 4k–16k 区间——朴素 attention 的 QK^T 与 PV 都要把中间矩阵落回 HBM，读写量按 O(N²) 膨胀，SM 大部分时间在等数据而不是在算。KV 也无法整段驻留，只能反复搬运。这类事故的工程含义是：分辨率档位不是免费打开的，注意力实现方式决定了这条曲线的拐点在哪里。</p>\n<p>异步 FA3 针对的正是这一段：把 Q tile 按序列切开，KV 以 TMA 异步预取进 shared memory 双缓冲，QK^T 走 FP8 tcgen05 MMA，softmax 在寄存器内做 online 归一化并写回 FP32 累加器，softmax 结果转 FP16 后与 V tile 做 PV GEMM，并与下一 tile 的 QK^T 重叠。跨 tile 用 online softmax 递推合并：</p>\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n<p>最后统一除以归一化因子再写回 HBM，直接喂给下一层 DiT block 的 LayerNorm。它把 attention 的 HBM 流量从 O(N²) 降到 O(N·d)，16k 序列下时延可降 2–4 倍。但它不解决“序列本身太长”的问题：N 仍是二次项出现在计算量里，只是把 IO 从主瓶颈位置上挪开；也不解决 KV 容量上限，双缓冲深度受 shared memory 容量约束，KV 驻留能力有限。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-7\">七 · 失效条件：三类边界必须提前判定</h3>\n<p>第一类是数值边界。FP8 只用于 QK^T、PV 保持 FP16，画质几乎无损的前提是 attention logit 的动态范围被 per-head scaling 压住。缺少 per-head scaling 时，logit 溢出会让高分辨率细节糊化，且这种退化在后处理阶段无法挽回——它不是噪声，而是权重分配错了。第二类是形状边界。warp-specialized 生产者/消费者流水对 head_dim 与 tile 形状挑剔，head_dim 与 tile 需 64/128 对齐；非对齐的 DiT 变体直接套 kernel 会触发重写或性能回退，流水无法按预期重叠，收益归零。第三类是资源边界。KV 双缓冲深度不足时，TMA 预取与 MMA 无法重叠，HBM 流量回落，16k 序列的时延收益被吃掉。可用的粗略判据是：</p>\n<div class=\"formula\">$$\\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}},\\ \\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</div>\n<p>只有当 HBM bound 明显高于 SM bound 时，异步流水才有加速空间；若 tile 太小导致 SM 侧先饱和，重叠就失去意义。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>满足时</th><th>不满足时</th></tr></thead><tbody><tr><td>序列长度</td><td>4k–16k，收益随时延增长</td><td>短序列下 IO 占比低，收益不明显</td></tr><tr><td>head_dim/tile</td><td>64/128 对齐，流水可重叠</td><td>需重写 kernel 或性能回退</td></tr><tr><td>per-head scaling</td><td>FP8 logit 不溢出，画质保持</td><td>细节糊化，不可后处理挽回</td></tr><tr><td>双缓冲深度</td><td>TMA 与 MMA 重叠</td><td>HBM 流量回落，时延收益被吃掉</td></tr></tbody></table>\n<p>系统代价要按三个维度记账：时延上，收益来自 IO 削减而非算力增加，16k 下 2–4 倍是上限区间，短序列摊薄后不明显；吞吐上，FP8 QK^T 在 Blackwell 上吞吐翻倍，但 PV 保持 FP16 意味着 PV 段仍是高精度路径，整体吞吐不是简单翻倍；显存与带宽上，KV tile 驻留 shared memory 双缓冲抬高了片上占用，双缓冲深度与 tile 大小互相挤压，head_dim 越大可用的缓冲层数越少。与 FlashAttention-2 的差别在于后者流水未针对 Blackwell 异步通路设计，TMA 与 tcgen05 的重叠吃不满。</p>\n<p>因此适用判断应落在请求形态上：1024² 以上、序列 4k–16k 的 DiT 采样是该方案的靶心；低于此区间应回到常规 attention 路径，高于此区间则要重新评估 shared memory 容量与双缓冲深度能否撑住，而不是指望同一 kernel 线性外推。批大小与 SLO 数值未给出时，容量规划只能以“单请求时延区间 + 双缓冲占用”做保守估算，把非对齐变体的重写成本提前计入排期。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-8\">八 · 边界不在“能不能跑”，而在“哪一步先崩”</h3>\n<p>一次 2048² 的 DiT 出图任务在夜里翻车：单卡 batch 拉到 8，采样步数不变，显存却先被 KV 撑爆，运维把 batch 砍到 2 之后 SM 利用率掉到低位，端到端时延反而比 batch=1 更长——朴素 attention 的 HBM 读写此时已是主瓶颈，KV 无法驻留，切 batch 只是把瓶颈从显存搬到带宽。这正是异步 FA3 要解决的问题域：序列长度 4k–16k 的全局注意力，把 IO 从 $O(N^2)$ 压到 $O(N\\cdot d)$，让 QK^T 的 GEMM 与 softmax 在 warp-specialized 生产者/消费者流水里重叠，KV tile 经 TMA 双缓冲驻留 shared memory。但它不解决另一类问题：head_dim 或 tile 形状非 64/128 对齐的 DiT 变体，kernel 要重写，流水无法按预期重叠，性能直接回退；它也不解决 per-head scaling 缺失导致的 logit 动态范围溢出，那属于数值问题，不是调度问题。</p>\n<p>失效条件可以按数据流定位。第一处是 FP8 QK^T：logit 动态范围一旦越界，高分辨率细节糊化，且这种退化在后处理里挽不回来，必须靠 per-head scaling 把量化误差压在注意力分数进入 softmax 之前。第二处是 shared memory 容量与双缓冲深度：深度不足时 TMA 预取与 tcgen05 MMA 无法重叠，HBM 流量回落到接近朴素路径，16k 序列那 2–4 倍的时延收益被吃掉。第三处是跨 tile 合并，online softmax 递推必须严格保持 running max 与归一化因子的更新顺序：</p>\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n<p>任何为了省寄存器而提前除归一化因子的改写，都会在 tile 边界引入偏差，序列越长偏差累积越明显。</p>\n<table class=\"mini\"><thead><tr><th>边界维度</th><th>成立条件</th><th>越界后的系统代价</th></tr></thead><tbody><tr><td>序列长度</td><td>4k–16k，收益随 N 增长</td><td>短序列下流水启动开销占比升高，加速比趋近于 1</td></tr><tr><td>形状对齐</td><td>head_dim、tile 为 64/128 对齐</td><td>需重写 kernel，或退回非流水实现，SM 利用率下降</td></tr><tr><td>数值范围</td><td>per-head scaling 覆盖 logit 动态范围</td><td>细节糊化，画质退化不可后处理挽回</td></tr><tr><td>片上容量</td><td>双缓冲深度足以覆盖 TMA 预取延迟</td><td>预取与 MMA 失配，HBM 流量回升，时延收益归零</td></tr></tbody></table>\n<p>工程判断上，这套方案适合“长序列 + 形状规整 + 可接受 FP8 QK^T 而 PV 保持 FP16”的 DiT 采样路径，规模上限由 shared memory 容量与双缓冲深度共同决定，而不是由算力决定；一旦 batch 与分辨率把 KV 推到无法驻留，先动的应是 tile 切分与缓冲深度，而不是 batch 大小。反过来说，若模型 head_dim 不在 64/128 网格上，或注意力 logit 分布跨度过大又无法做 per-head 校准，那么引入它的第一笔代价就是 kernel 重写与画质回归测试，这笔账要在选型阶段就算清。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-9\">九 · Q tile 切分与 TMA 预取：把请求变成可流水的 tile 序列</h3>\n<p>进入 kernel 的第一个动作不是算，而是切。对每个请求，注意力层拿到形状为 [N, d] 的 Q、K、V（N 即 4k–16k 的序列长度，d 为 head_dim），按 Q 的行方向切成 <span class=\"inline-code\">BM×d</span> 的 Q tile，KV 侧则按 <span class=\"inline-code\">BN×d</span> 的 KV tile 组织。切分粒度由 shared memory 容量与双缓冲深度共同决定：每个 KV tile 要在 SMEM 里占两份（当前计算 + 下一份预取），所以 <span class=\"inline-code\">2·BN·d·sizeof(dtype)</span> 必须落在 SMEM 预算内，这就是规模上限的直接来源。输入是 HBM 上的连续 QKV 张量，输出是一串 tile 描述符（地址、步长、边界掩码），代价是一次性的索引计算，可忽略，但切分形状一旦非 64/128 对齐，后续 warp-specialized 流水的角色划分就失效。</p>\n<p>预取阶段由生产者 warp 发起 TMA 异步拷贝：把第 <span class=\"inline-code\">j+1</span> 个 KV tile 从 HBM 搬到 SMEM 的第二块缓冲，同时消费者 warp 正在对第 <span class=\"inline-code\">j</span> 个 tile 做 MMA。TMA 的输入是全局内存地址与 tensor map，输出是 SMEM 中已就绪的 tile 加一个 mbarrier 完成信号；代价是 HBM 带宽占用，但因为 KV 只被读一次、每个 Q tile 复用整段 KV，总流量从朴素 attention 的 O(N²) 降到 O(N·d)。以 16k 序列、d=128、FP16 KV 为例，朴素实现每个 Q 行都要重读全部 KV，HBM 读写量随 N² 膨胀；分块后 KV 每个元素只进入 SMEM 一次，流量差出一个数量级——这正是 <span class=\"inline-code\">IO∝N²d/SRAM</span> 所刻画的瓶颈被削平的地方。双缓冲深度不足时，TMA 与 MMA 无法重叠，HBM 流量回落，16k 序列的时延收益被吃掉。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-10\">十 · QK^T 走 FP8 tcgen05 MMA：GEMM 与 softmax 的角色分离</h3>\n<p>消费者侧的第一个计算是 <span class=\"formula\">$$S_{j}=q_{i}k_{j}^{\\top}/\\sqrt{d}$$</span> 的批量 GEMM。Q tile 常驻 SMEM（或经 TMEM 中转），KV tile 刚由 TMA 送达，两者以 FP8 精度送入 tcgen05 MMA。这里的关键不是 MMA 本身，而是角色分离：warp-specialized 设计把生产者（TMA 搬运）、MMA 发射、softmax 计算拆成不同 warp 组，让 QK^T 的 GEMM 在 tensor core 上跑的同时，上一 tile 的 softmax 在寄存器与 FP32 累加器上跑。输入是 FP8 的 Q/K tile 与 per-head scaling 因子，输出是 FP32 的 logit tile（写回寄存器或 TMEM），代价是 tensor core 占用与 FP32 累加器容量——后者直接限制了同时驻留的 tile 数。</p>\n<p>FP8 在这里是纯吞吐交易：Blackwell 上 FP8 MMA 吞吐相对 FP16 翻倍，代价是 logit 动态范围被压缩。attention logit 的分布随分辨率变化剧烈，高分辨率 DiT 的注意力图往往有尖锐峰值，缺少 per-head scaling 时 FP8 量化会把峰值削平，表现为高分辨率细节糊化，且这种退化在后处理阶段不可挽回。因此每个 head 在进入 GEMM 前必须有一个标量缩放，把 logit 拉到 FP8 可表示的区间；这个缩放的计算与广播本身很便宜，但它决定了这条路径能不能用。非 64/128 对齐的 head_dim 会让 MMA 的 tile 形状退化，warp-specialized 流水无法按预期重叠，只能重写 kernel。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-11\">十一 · 寄存器内 online softmax：跨 tile 递推的状态机</h3>\n<p>logit tile 到达后，softmax 在寄存器内完成 online 归一化，不落 HBM。每个 Q 行维护三个状态：running max <span class=\"inline-code\">m</span>、归一化因子 <span class=\"inline-code\">ℓ</span>、FP32 输出累加器 <span class=\"inline-code\">O</span>。对第 <span class=\"inline-code\">j</span> 个 KV tile，先求本 tile 的行最大值 <span class=\"inline-code\">m̃</span>，再按</p>\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n<p>更新状态，并用 <span class=\"inline-code\">e^{m_{i-1}-m_i}</span> 缩放已累积的 <span class=\"inline-code\">O</span>。输入是 FP32 logit tile 与上一 tile 的状态，输出是更新后的 <span class=\"inline-code\">m/ℓ/O</span> 与一份待做 PV 的 FP16 概率 tile。代价是寄存器压力：每个 Q 行要占 <span class=\"inline-code\">d</span> 个 FP32 累加器，加上 max 与 ℓ，Q tile 越大寄存器越紧张，这也是 BM 不能随意放大的原因。伪代码层面，这一步是纯标量/向量运算，与下一 tile 的 QK^T 在时间上重叠，因此它的延迟被 GEMM 掩盖，但它的正确性决定整个递推链。</p>\n<p>跨 tile 合并的工程含义是：KV 序列再长，也不需要把完整 attention 矩阵物化。16k 序列、d=128 时，完整 logit 矩阵是 16k×16k 的规模，FP16 下远超单卡显存；online 递推把它压成每行 <span class=\"inline-code\">d</span> 个累加器加两个标量，显存代价从 O(N²) 降到 O(N·d)。代价的另一面是数值：<span class=\"inline-code\">e^{m_{i-1}-m_i}</span> 的缩放必须与 max 更新严格同步，任何一步顺序错乱都会让累加器溢出或下溢，而 FP8 的窄动态范围让这个同步更敏感。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-12\">十二 · PV GEMM 与下一 tile 的 QK^T 重叠：FP16 精度的守门</h3>\n<p>softmax 输出的 FP16 概率 tile 与 SMEM 中的 V tile 做 PV GEMM，累加进 FP32 的 <span class=\"inline-code\">O</span>。这一步刻意保持 FP16 而非 FP8：概率值集中在 [0,1] 且大量接近 0，FP8 的尾数不足以区分小概率对输出的贡献，量化误差会直接进入最终特征，表现为画质退化。因此整条流水是混合精度的——QK^T 用 FP8 换吞吐，PV 用 FP16 守精度，吞吐翻倍而画质几乎无损的说法正来自这个不对称。输入是 FP16 概率 tile、FP16 V tile 与 FP32 累加器，输出是更新后的 <span class=\"inline-code\">O</span>；代价是 PV GEMM 的 tensor core 时间无法享受 FP8 的翻倍，它成为流水里的次瓶颈。</p>\n<p>重叠是这一步的核心机制：PV GEMM 与下一个 KV tile 的 QK^T 由不同 warp 组发射，前者在 tensor core 上跑 FP16 MMA 时，后者已经在同一批 tensor core 或相邻资源上启动 FP8 MMA。调度器要保证 softmax 结果转 FP16 的转换不阻塞 PV 发射，否则重叠断裂。以 16k 序列为例，若每个 tile 的 PV 与下一 QK^T 完全重叠，SM 的有效占用接近饱和；一旦重叠失败，SM 利用率回落到单条流水线的水平，时延收益从 2–4 倍缩水到接近朴素实现。这就是 <span class=\"inline-code\">Speedup≈HBM bound/SM bound</span> 的直观含义：收益上限由两条流水线的重叠质量决定，而不是由单条流水线的峰值算力决定。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-13\">十三 · 归一化收尾与写回：直接喂给下一层 LayerNorm</h3>\n<p>所有 KV tile 遍历完后，每个 Q 行的 <span class=\"inline-code\">O</span> 还是未归一化的加权和，需要统一除以 <span class=\"inline-code\">ℓ_i</span> 得到 <span class=\"formula\">$$O_{i}=\\sum_{j}\\frac{\\exp(q_{i}k_{j}^{\\top}/\\sqrt{d}-m_{i})}{\\ell_{i}}v_{j}$$</span> 的最终结果。输入是 FP32 累加器与归一化因子，输出是 FP16 的 attention 输出 tile，代价是一次逐元素的除法与类型转换，计算量可忽略但必须等最后一个 tile 的 PV 完成，因此它是流水末端的串行点。写回 HBM 时按 DiT block 的布局直接落到下一层 LayerNorm 的输入位置，避免额外的重排 kernel——这一步省下的是 kernel launch 与一次全量读写，对 4k–16k 序列的端到端时延有实质贡献。</p>\n<p>写回的带宽代价与输出规模成正比：N×d 的 FP16 输出，相对 KV 的读取量小得多，但在多层堆叠的 DiT 里，每层都要写一次、下一层再读一次，累计起来仍是可观的 HBM 流量。因此把写回地址对齐到 LayerNorm 的输入布局、让下一层直接消费，是把 O(N·d) 流量压到下限的工程手段。若中间插入重排或转置，流量翻倍，16k 序列下这部分开销会侵蚀 attention 本身省下的收益。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-14\">十四 · 步骤间的耦合代价：形状、缓冲深度与缩放因子的联合约束</h3>\n<p>把五步串起来看，真正的工程约束不在单步，而在耦合。Q tile 大小 BM 受寄存器容量限制（softmax 状态），KV tile 大小 BN 受 SMEM 双缓冲限制（TMA 预取），head_dim 必须 64/128 对齐才能让 tcgen05 MMA 与 warp-specialized 角色划分同时成立，per-head scaling 又要求 logit 动态范围在 FP8 内可表示。四个约束里任何一个不满足，流水就退化：BN 太小则 TMA 预取与 MMA 无法重叠，HBM 流量回落；BM 太大则 softmax 寄存器溢出，online 递推被迫落 SMEM，延迟上升；head_dim 非对齐则 MMA 形状退化，需要重写 kernel；缺 scaling 则画质糊化。这些不是可调参数，而是设计空间的硬边界。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>Q tile 切分</td><td>HBM 上 QKV 张量</td><td>tile 描述符</td><td>索引计算，可忽略；形状决定后续可行性</td></tr><tr><td>TMA 预取 KV</td><td>全局地址、tensor map</td><td>SMEM 双缓冲 tile</td><td>HBM 带宽；双缓冲深度不足则重叠断裂</td></tr><tr><td>QK^T FP8 MMA</td><td>FP8 Q/K tile、per-head scaling</td><td>FP32 logit tile</td><td>tensor core 占用、FP32 累加器容量</td></tr><tr><td>online softmax</td><td>logit tile、m/ℓ/O 状态</td><td>FP16 概率 tile、更新状态</td><td>寄存器压力；数值同步敏感性</td></tr><tr><td>PV FP16 GEMM</td><td>概率 tile、V tile、FP32 O</td><td>更新后的 O</td><td>FP16 MMA 时间，成为次瓶颈</td></tr><tr><td>归一化写回</td><td>FP32 O、ℓ</td><td>FP16 输出，对齐 LayerNorm</td><td>末端串行点；多层累计 HBM 写流量</td></tr></tbody></table>\n<p>具体到一个 16k 序列、d=128 的 DiT 采样请求：Q tile 与 KV tile 按 128 对齐切分，KV 双缓冲在 SMEM 里驻留两份，TMA 预取第 j+1 块时 FP8 QK^T 正在算第 j 块，softmax 的 FP32 累加器在寄存器里滚动，PV 的 FP16 GEMM 与下一块 QK^T 并行发射，最后统一除以 ℓ 写回并对齐到下一层 LayerNorm。整条链的时延收益来自 HBM 流量从 O(N²) 降到 O(N·d) 与两条流水线的重叠，2–4 倍的降幅在 16k 序列下成立；而收益能否兑现，取决于双缓冲深度、tile 对齐与 per-head scaling 这三个工程判断是否同时做对。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-15\">十五 · 流水线的断点：TMA 双缓冲、FP8 缩放与对齐约束如何吃掉收益</h3>\n\n<p>把这条流水按数据流拆开看，每个阶段的代价都落在不同的硬件资源上，失效点也各不相同。第一阶段是 Q tile 切分与 KV 预取：Q 按序列切成 tile 常驻寄存器/TMEM，KV tile 由 TMA 异步搬入 shared memory 双缓冲。这一步的代价是 shared memory 容量——双缓冲意味着 KV tile 占用的 SMEM 翻倍，而 SMEM 是每 SM 固定资源，因此双缓冲深度与 tile 尺寸直接决定单 SM 能承载多大的 KV 窗口。当双缓冲深度不足时，TMA 预取与 tcgen05 MMA 无法重叠，HBM 流量回落到接近朴素 attention 的水平，16k 序列下 2–4 倍的时延收益被直接吃掉。这是本方案最隐蔽的失败模式：kernel 能跑通、数值也正确，但性能退回起点，且 profiler 上表现为 MMA 空闲等待而非显存带宽打满，容易被误判为算力问题。</p>\n\n<p>第二阶段是 QK^T 与 online softmax 的交叠。QK^T 走 FP8 tcgen05 MMA，softmax 在寄存器内做 online 归一化并写回 FP32 累加器，随后结果转 FP16 与 V tile 做 PV GEMM，与下一 tile 的 QK^T 重叠。这里的系统代价是精度预算的分配：FP8 只压在 QK^T 上，PV 保持 FP16，因此误差只经由 logit 进入 softmax 再被归一化放大或压缩。FP8 对 attention logit 的动态范围敏感，缺少 per-head scaling 时 logit 溢出会让高分辨率细节糊化，而这种退化发生在 softmax 内部，后处理无法挽回。per-head scaling 的代价是每个 head 需维护独立的 scale 并在跨 tile 递推时保持一致，否则 running max 与归一化因子的递推会失配。跨 tile 合并按</p>\n\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n\n<p>递推，$m$ 为 running max、$\\ell$ 为归一化因子，最后统一除以归一化因子得到输出。这个递推要求每个 tile 的 $\\tilde m_i$ 与 $\\tilde\\ell_i$ 在 FP32 下计算，若为省寄存器把累加器降到 FP16，长序列（16k）下 $\\ell$ 的累加会丢精度，表现为远距离 token 的注意力权重被系统性低估——这正是 DiT 全局注意力最不能接受的误差方向。</p>\n\n<p>第三阶段是输出写回与下游衔接：结果写回 HBM 并直接喂给下一层 DiT block 的 LayerNorm。代价在 HBM 带宽上，但因为 HBM 流量已从 $O(N^2)$ 降到 $O(N\\cdot d)$，这一段的绝对开销随序列长度线性增长而非平方增长，16k 下相对朴素 attention 的优势即来源于此。真正的边界在形状约束：warp-specialized 生产者/消费者流水对 head_dim 与 tile 形状挑剔，head_dim 或 tile 非 64/128 对齐的 DiT 变体直接套用 kernel 会触发重写或性能回退，流水无法按预期重叠。规模上限同时受 shared memory 容量与双缓冲深度约束，head_dim 越大、tile 越大，可容纳的 KV 窗口越小，超过某个序列长度后必须退回分块重算或换 kernel。工程判断上，先确认 head_dim 与 tile 是否 64/128 对齐、SMEM 能否撑起所需双缓冲深度，再谈 FP8 与 per-head scaling 的精度调优；顺序颠倒会在一个注定回退的 kernel 上做无效的数值调试。</p>\n\n<table class=\"mini\"><thead><tr><th>阶段</th><th>输入→输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>KV 预取</td><td>KV tile→SMEM 双缓冲</td><td>SMEM 容量、TMA 与 MMA 重叠度</td><td>双缓冲深度不足，HBM 流量回落</td></tr><tr><td>QK^T + softmax</td><td>Q、K→FP32 累加器</td><td>FP8 精度预算、per-head scale 维护</td><td>缺 scaling 致 logit 溢出、细节糊化</td></tr><tr><td>PV GEMM</td><td>softmax 结果、V→FP16 输出</td><td>与下一 tile QK^T 的重叠窗口</td><td>tile 形状非对齐，流水断流</td></tr><tr><td>写回</td><td>输出→HBM→LayerNorm</td><td>HBM 带宽，随 $N\\cdot d$ 线性</td><td>序列超 SMEM 上限需重算</td></tr></tbody></table>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-16\">十六 · 异步 FA3 的边界：流水何时失效、代价落在哪里</h3>\n<p>这套流水的前提是“tile 形状与硬件通路同构”。Q tile 切分后，KV tile 经 TMA 预取进 shared memory 双缓冲，生产者 warp 只负责搬运、消费者 warp 只负责 tcgen05 MMA 与寄存器内 online softmax，二者靠 barrier 解耦。一旦 head_dim 不是 64/128 的整数倍，TMA 的 box 维度与 swizzle 模式就要重排，双缓冲的槽位对齐被打断，生产者与消费者的节奏差被迫用额外同步补齐——重叠窗口塌缩，SM 侧从“GEMM 与 softmax 并行”退化为串行，此时即便 HBM 流量仍是 O(N·d)，端到端也拿不到 16k 序列下 2–4 倍的时延收益。非对齐的 DiT 变体不是调参能救的，必须重写 kernel 的搬运与 MMA 描述符。</p>\n<p>第二个边界在数值侧。QK^T 走 FP8 使 tcgen05 吞吐翻倍，但 attention logit 的动态范围随分辨率上升而变宽：1024² 以上、序列 4k–16k 时，不同 head 的 logit 峰值差异显著，缺少 per-head scaling 会让量化步长吃掉尾部大值，softmax 分布被压平，高分辨率细节糊化且不可后处理挽回。工程上必须在每个 head 上维护独立的 scale，并在 online 递推中保持 $m_i=\\max(m_{i-1},\\tilde m_i)$、$\\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$ 的数值一致性——running max 一旦因量化偏差漂移，后续 tile 的归一化因子就整体错位。PV 保持 FP16 正是为了不让这个误差进入值通路。</p>\n<p>第三个代价是 shared memory 预算。双缓冲深度直接决定 TMA 预取能否盖住 MMA 的延迟：深度不足时预取与计算无法重叠，HBM 流量回落到接近朴素 attention 的水平，收益被吃掉；深度过大则挤压 KV tile 的驻留空间，规模上限受 shared memory 容量约束。以 16k 序列、head_dim 128 为例，单 head 的 KV 全量已无法驻留，只能靠 tile 流式推进，缓冲深度与 tile 尺寸构成一个硬约束的二维权衡。可用如下判据粗筛配置：</p>\n<div class=\"formula\">$$\\text{util}\\approx\\frac{T_{\\text{MMA}}}{T_{\\text{MMA}}+T_{\\text{TMA}}^{\\text{miss}}},\\quad \\text{buf}\\ge \\frac{\\text{BW}\\cdot T_{\\text{MMA}}}{\\text{tile}_{KV}}$$</div>\n<p>其中 $T_{\\text{TMA}}^{\\text{miss}}$ 是预取未及时到达造成的停顿。该式说明：缓冲深度必须按 MMA 单 tile 时间与 HBM 带宽的乘积来配，而不是按“越大越好”拍脑袋。落到系统账上，这套方案的代价集中在三处——kernel 可移植性（非 64/128 对齐即重写）、数值稳定性（per-head scaling 与 FP32 累加器不可省）、显存带宽的有效利用率（双缓冲深度决定 HBM 流量能否真正压到 O(N·d)）。三者任一失守，16k 序列的时延优势就不再成立，此时应回退到 FP16 QK^T 的保守配置而非硬套 FP8 流水。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-17\">十七 · 从三重求和到分块递推：公式逐项拆解</h3>\n<p>核心公式写全了三个层次的信息：结果、归一化、以及代价结构。逐项看，$q_i k_j^{\\top}/\\sqrt{d}$ 是缩放点积，$\\sqrt{d}$ 的存在是为了让 logit 方差与 $d$ 无关，从而 softmax 不因 head_dim 增大而饱和；$-m_i$ 是数值稳定项，$m_i$ 为该行在已处理 tile 上的 running max；$\\ell_i$ 是归一化因子，等价于 $\\sum_j \\exp(q_i k_j^{\\top}/\\sqrt{d}-m_i)$；$v_j$ 是值向量。整个式子的含义是：输出是值向量的凸组合，权重由指数化后的相似度给出。朴素实现把这个凸组合一次性算完，代价是中间矩阵 $N\\times N$ 必须落到 HBM；分块实现把它拆成按 KV tile 递推的累加，中间量只存在于寄存器与 shared memory。</p>\n<p>推导的关键一步在归一化因子的递推。设已处理 $i-1$ 个 KV tile，得到 $(m_{i-1},\\ell_{i-1})$ 与部分输出 $\\tilde{O}_{i-1}$；新 tile 的局部最大为 $\\tilde{m}_i$、局部归一化因子为 $\\tilde{\\ell}_i$。合并时先取新 max：</p>\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n<p>输出累加器同步缩放：$\\tilde{O}_i=e^{m_{i-1}-m_i}\\tilde{O}_{i-1}+e^{\\tilde m_i-m_i}\\tilde{O}_i^{\\text{local}}$，最终 $O_i=\\tilde{O}_i/\\ell_i$。这一步之所以是“关键”，是因为它把“必须先知道全局 max 才能算 softmax”的顺序依赖打破了——每个 tile 可以独立算局部 max 与局部和，再以 $O(1)$ 的状态合并。没有这个递推，分块就只是把大矩阵切成小块但仍然要两遍扫描，HBM 流量降不下来。注意缩放因子 $e^{m_{i-1}-m_i}$ 恒小于等于 1，因此累加器不会溢出，这也是 FP32 累加器足够的原因。</p>\n<p>代价项 $\\text{IO}\\propto N^{2}d/\\text{SRAM}$ 说明朴素 attention 的 HBM 流量随序列长度平方增长，而分块后流量正比于 $N\\cdot d$（每块 Q 读一遍 KV，KV 总量 $N\\cdot d$）。$\\text{Speedup}\\approx\\text{HBM bound}/\\text{SM bound}$ 则给出加速上限：当 kernel 从 HBM 受限转为 SM 受限，加速比就由两者的时间比决定。对 16k 序列的 DiT 采样，这个比值落在 2–4 倍区间；序列越短，HBM 占比越低，收益越接近 1。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-18\">十八 · 精度分工的推导：为什么 FP8 只给 QK^T</h3>\n<p>把 QK^T 放到 FP8、PV 保持 FP16，不是随手选的，而是由误差传播路径决定的。QK^T 的输出进入 softmax，softmax 是指数压缩：logit 的绝对误差 $\\epsilon$ 经 $\\exp$ 后变成权重的相对误差约 $\\epsilon$，但权重随后被归一化，且大量接近零的权重对输出的贡献可忽略。也就是说 QK^T 的量化误差被 softmax 的“选择性”吸收了一部分。而 PV 是线性组合，V 的量化误差直接按权重加权进入输出，没有任何压缩环节，因此必须保持高精度。这就是“QK^T 用 FP8、PV 用 FP16”的推导依据。</p>\n<p>但 softmax 的吸收能力有边界。FP8 E4M3 的动态范围有限，若某个 head 的 logit 分布跨度大，per-tensor 的单一缩放因子会让小 logit 落入次正规区、大 logit 逼近饱和，指数化后权重分布被扭曲，表现为高分辨率细节糊化。因此需要 per-head scaling：每个 head 独立统计 logit 的动态范围，选一个缩放因子把 logit 映射到 FP8 的可用区间。这一步在 kernel 里体现为 QK^T MMA 之前对 Q 或 K 乘一个标量、之后除回，标量本身由校准或运行时统计得到。缺少这一步，画质退化无法靠后处理挽回，因为信息在 softmax 之前就丢了。</p>\n<p>系统代价上，FP8 QK^T 在 Blackwell 的 tcgen05 MMA 上吞吐相对 FP16 翻倍，这是收益侧；代价侧是 per-head scaling 引入的额外标量运算与校准开销，以及动态范围监控的工程复杂度。对 DiT 这种对细节敏感的场景，这个交换是划算的：QK^T 占 attention 计算量的大头，PV 的 FP16 保证了输出精度。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-19\">十九 · 伪代码：把流水落到可实现</h3>\n<p>下面的伪代码按数据流顺序给出，重点在双缓冲与 warp 分工，不涉及具体指令。</p>\n<ul>\n<li>外层按 Q tile 遍历；每个 Q tile 载入寄存器，初始化 $m=-\\infty$、$\\ell=0$、$\\tilde{O}=0$（FP32）。</li>\n<li>KV 以 TMA 异步预取到 shared memory 的两个缓冲区，buffer A 供当前 tile 的 MMA 消费，buffer B 在后台填充下一 tile；TMA 完成由 mbarrier 通知，消费者 warp 等待 barrier 而非轮询。</li>\n<li>生产者 warp 只发 TMA 与 barrier arrive，消费者 warp 只发 MMA 与 softmax，二者通过 barrier 解耦，这就是 warp-specialized 的实质。</li>\n<li>对每个 KV tile：QK^T 走 FP8 tcgen05 MMA 得到 logit tile；在寄存器内做 online 归一化，更新 $\\tilde{m}$、$\\tilde{\\ell}$，按第一节的递推式缩放累加器；softmax 结果转 FP16。</li>\n<li>PV GEMM 用 FP16 的 softmax 结果与 V tile 相乘，累加进 $\\tilde{O}$；该 GEMM 与下一 tile 的 QK^T 在时间上重叠，因为二者使用不同的执行单元与不同的 shared memory 缓冲区。</li>\n<li>KV tile 全部消费完后，$O=\\tilde{O}/\\ell$，写回 HBM，直接作为下一层 DiT block 的 LayerNorm 输入，避免一次额外的全局读写。</li>\n</ul>\n<p>伪代码里最容易被忽略的是 barrier 的粒度。若每个 KV tile 只用一个 barrier，生产者在填充 buffer B 时消费者可能还在等 buffer A 的 MMA 完成，重叠窗口被压缩。正确做法是每个缓冲区一组 barrier，形成“填充—消费—回收”的三态循环，双缓冲深度为 2 时重叠率最高，深度为 1 时退化为串行。这就是失败模式里“KV 双缓冲深度不足时 TMA 预取与 MMA 无法重叠”的机制来源：深度不足直接让 HBM 流量回落，16k 序列的时延收益被吃掉。</p>\n<p>另一个实现细节是 softmax 的写回位置。把 FP32 累加器放在寄存器而非 shared memory，是为了避免每个 tile 一次 shared memory 往返；但寄存器压力随 head_dim 增长，128 维 head 的累加器已占可观份额，这也是 tile 形状必须对齐的原因之一。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-20\">二十 · 形状约束的代价分析</h3>\n<p>warp-specialized 流水对 head_dim 与 tile 形状挑剔，根源在 MMA 的指令形状与 shared memory 的布局。tcgen05 MMA 的 K 维与 N 维有固定的对齐要求，64/128 是常见档位；若 DiT 变体的 head_dim 是 80 或 96，QK^T 的 K 维无法直接映射到 MMA 形状，需要补零或拆分，补零浪费算力，拆分增加指令数。tile 形状同理：Q tile 的行数决定寄存器占用，KV tile 的列数决定 shared memory 占用，二者共同决定双缓冲能开多深。</p>\n<p>代价可以定性表述：非对齐变体要么重写 kernel（工程成本），要么套用现有 kernel 后性能回退（运行时成本）。回退的机制是流水无法按预期重叠——补零后的 MMA 有效算力下降，barrier 等待时间相对变长，SM 利用率反而低于朴素实现。规模上限也在这里：shared memory 容量决定了单个 KV tile 的最大尺寸与双缓冲深度，head_dim 越大、tile 越大，能开的缓冲越少，重叠窗口越窄。</p>\n<p>工程判断上，对 1024² 以上、序列 4k–16k 的 DiT 采样，优先保证 head_dim 落在 64/128 档位，把非对齐的变体作为单独的 kernel 分支处理，而不是让通用 kernel 去兼容所有形状。这与“收益随序列长度增长”的规律一致：短序列下重写 kernel 的固定成本摊不薄，长序列下对齐带来的重叠收益才显现。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-21\">二十一 · 与相邻实现的边界：一句话指路后的取舍</h3>\n<p>FlashAttention-2 的流水没有针对 Blackwell 的异步通路设计，TMA 与 tcgen05 的潜力未被利用，因此在 Blackwell 上直接移植 FA2 只能拿到分块带来的 HBM 收益，拿不到异步重叠带来的额外收益。本实现把生产者/消费者解耦、把 QK^T 与 PV 放到不同精度路径，才把 $\\text{HBM bound}/\\text{SM bound}$ 的比值真正兑现。至于 FP8 注意力的通用做法，本卷另有条目专讲 GEMM 侧的精度策略，此处只强调分工：QK^T 的 FP8 需要 per-head scaling 兜底，PV 的 FP16 是画质底线，二者不可互换。</p>\n<p>取舍的落点是：当序列在 4k 以下，HBM 受限程度低，异步流水的复杂度换不来时延；当序列进入 16k，双缓冲深度与 per-head scaling 成为必须项，否则收益被失败模式吃掉。这个边界不是调参问题，而是由 shared memory 容量与 logit 动态范围两个硬约束共同划定的。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-22\">二十二 · 异步 FA3 在 DiT 上的失效边界：从 online softmax 递推到 shared memory 容量墙</h3>\n\n<p>核心公式的每一项都对应一个可被打破的物理约束。$O_i=\\sum_j \\exp(q_i k_j^\\top/\\sqrt{d}-m_i)/\\ell_i \\cdot v_j$ 中，$m_i$ 是 running max、$\\ell_i$ 是归一化因子，二者构成跨 tile 合并的全部状态；$\\text{IO}\\propto N^2 d/\\text{SRAM}$ 说明 HBM 流量与 tile 驻留能力成反比；$\\text{Speedup}\\approx\\text{HBM bound}/\\text{SM bound}$ 则给出收益上限——只有当 SM 侧计算被充分隐藏时，这个比值才接近实测值。推导的关键一步在于把单 tile 的局部 softmax 提升为全局递推：设第 $i$ 个 KV tile 的局部最大值为 $\\tilde m_i$、局部归一化因子为 $\\tilde\\ell_i$，则合并必须按</p>\n\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n\n<p>执行。这一步不是数学装饰，而是数值稳定性的唯一闸门：若省略 $e^{m_{i-1}-m_i}$ 的重缩放，FP32 累加器在 16k 序列上会因指数项跨 tile 漂移而溢出。伪代码落到可实现层面，循环体应写成「TMA 预取 KV tile 到双缓冲 → FP8 tcgen05 MMA 出 $q_i k_j^\\top$ → 寄存器内 online 归一化写回 FP32 累加器 → 转 FP16 与 V tile 做 PV GEMM，同时下一 tile 的 QK^T 已在另一 warp group 上启动」。这里每个 tile 的 PV 结果必须携带自己的 $\\tilde m_i,\\tilde\\ell_i$ 参与递推，而不是等全部 tile 结束再统一归一化——后者会让累加器长期持有未缩放的部分和，在 16k 序列下把 FP32 的动态范围推到边缘。系统代价直接体现在 shared memory 上：双缓冲深度每增加一级，就多占一份 KV tile 的容量，而 Blackwell 的 shared memory 总量固定，深度不足时 TMA 预取与 MMA 无法重叠，HBM 流量回落，16k 序列下 2–4 倍的时延收益被逐级吃掉。</p>\n\n<p>失效条件的第一类是数值型。FP8 QK^T 对 attention logit 的动态范围极其敏感，缺少 per-head scaling 时，高分辨率 DiT 的 logit 分布尾部被截断，1024² 以上分辨率的高频细节直接糊化，且这种退化发生在 softmax 之前，任何后处理都无法挽回。per-head scaling 不是可选项：每个 head 的 $q k^\\top$ 幅值分布不同，统一 scale 会让部分 head 饱和、部分 head 欠利用 FP8 的表示区间。第二类是形状型。warp-specialized 生产者/消费者流水对 head_dim 与 tile 形状挑剔，非 64/128 对齐的 DiT 变体直接套用 kernel 会触发重写或性能回退——流水无法按预期重叠时，$\\text{Speedup}$ 公式中的 SM bound 一侧反而恶化，异步通路退化为同步串行。第三类是容量型，即上文所述的双缓冲深度约束，它决定了规模上限：序列越长，KV tile 越多，但 shared memory 不随序列增长，深度只能靠缩小 tile 换取，而 tile 缩小又反过来削弱 MMA 的算术强度。</p>\n\n<table class=\"mini\"><thead><tr><th>失效维度</th><th>触发条件</th><th>系统表现</th><th>工程对策</th></tr></thead><tbody><tr><td>数值</td><td>缺 per-head scaling，logit 动态范围溢出</td><td>高分辨率细节糊化，不可后处理挽回</td><td>逐 head 标定 scale，PV 保持 FP16</td></tr><tr><td>形状</td><td>head_dim 或 tile 非 64/128 对齐</td><td>流水不重叠，性能回退</td><td>重写 kernel 或填充对齐</td></tr><tr><td>容量</td><td>KV 双缓冲深度不足</td><td>TMA 与 MMA 串行，HBM 流量回落</td><td>缩 tile 换深度，权衡算术强度</td></tr></tbody></table>\n\n<p>把这三类边界放回 $\\text{IO}\\propto N^2 d/\\text{SRAM}$ 看，收益的本质是用 SRAM 容量换 HBM 流量：16k 序列下朴素 attention 的 HBM 读写是主瓶颈，而 FA3 把流量压到 $O(N\\cdot d)$ 的前提是 KV tile 能在 shared memory 中驻留并被双缓冲复用。一旦对齐失败或深度不足，SRAM 这一项实际变小，IO 项回升，SM 利用率随之跌落。因此工程判断应落在「先验形状、再验数值、后调深度」的顺序上：非 64/128 对齐的 DiT 变体在 kernel 层面就应判定为不可直接套用，per-head scaling 必须在离线标定阶段固化进权重或运行时元数据，而双缓冲深度则需按目标序列长度与 shared memory 预算反解，而不是沿用低分辨率配置。异步 FA3 不是普适加速器，它的收益区间被序列长度、对齐约束与 SRAM 容量三者共同框定，越界即失效。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-23\">二十三 · 异步 FA3 的收益边界与失效面：从 online softmax 递推到流水深度约束</h3>\n<p>本方案的速度上限由 HBM bound 与 SM bound 的比值决定，<span class=\"formula\">$$O_{i}=\\sum_{j}\\frac{\\exp(q_{i}k_{j}^{\\top}/\\sqrt{d}-m_{i})}{\\ell_{i}}v_{j},\\quad \\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}},\\ \\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</span> 这一式子给出的不是承诺而是天花板：只有当朴素 attention 确实被 HBM 读写卡住时，把 KV tile 驻留 shared memory 才有意义。序列越长，$N^2 d/\\text{SRAM}$ 项越占主导，收益才越显著；4k 附近收益有限，16k 时才有 2–4 倍时延下降的空间。反过来，若某一层 attention 的 $d$ 很小或 head 数很少，SM bound 提前成为瓶颈，异步流水再精细也换不来吞吐。</p>\n<p>跨 tile 合并的正确性依赖递推而非一次性归一化：<span class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</span> 每一步都要用新的 running max 重标定旧累加器，否则 FP8 QK^T 输出的 logit 动态范围一旦超出 per-head scaling 的覆盖区间，指数项溢出会把高分辨率纹理细节抹平，且这种退化发生在 softmax 内部，后处理无法挽回。工程上应把 per-head scale 与 running max 一起纳入 kernel 参数校验，对超出预设范围的 head 直接回退到 FP16 QK^T，而不是让整层画质塌陷。</p>\n<p>流水能否重叠取决于双缓冲深度与 tile 形状的对齐。KV tile 以 TMA 预取进 shared memory 双缓冲，若深度不足，预取与 tcgen05 MMA 无法交叠，HBM 流量回落到接近朴素 attention 的水平，16k 序列的时延收益被直接吃掉；而 head_dim 与 tile 非 64/128 对齐的 DiT 变体，warp-specialized 生产者/消费者分工失效，需重写 kernel 或接受性能回退。下表给出三类边界条件下的判断依据：</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>失效表现</th><th>系统代价</th></tr></thead><tbody><tr><td>per-head scaling 缺失或范围不足</td><td>logit 溢出，细节糊化</td><td>画质退化不可后处理修复</td></tr><tr><td>head_dim/tile 非 64/128 对齐</td><td>流水无法重叠</td><td>kernel 重写或吞吐回退</td></tr><tr><td>KV 双缓冲深度不足</td><td>TMA 与 MMA 串行</td><td>HBM 流量回升，时延收益消失</td></tr></tbody></table>\n<p>因此部署时的判断顺序应是：先确认序列长度落在 4k–16k 且 HBM 确为主瓶颈，再校验 head_dim 与 tile 的 64/128 对齐性，最后按 shared memory 容量反推双缓冲深度——深度每减少一级，TMA 预取窗口就缩短一段，异步收益随之衰减，这条约束比 FP8 吞吐翻倍更早决定实际时延。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-24\">二十四 · 请求形态：序列长度是配方的第一变量</h3>\n<p>异步 FA3 的收益不是常数，它随序列长度单调增长。1024² 以下的分辨率，DiT 全局注意力的序列长度落在 4k 以内，此时朴素 attention 的 HBM 读写虽已开始吃紧，但 QK^T 与 PV 的 GEMM 仍能占据相当比例的 SM 周期，异步流水的重叠空间有限；把 warp-specialized 生产者/消费者搬上来，换来的只是流水启动开销与寄存器压力。真正进入配方甜区的是 1024² 以上、序列长度 4k–16k 的采样请求：HBM 流量按 O(N²) 增长而 SM 计算按 O(N²·d) 增长，两者的比值决定了瓶颈归属，序列越长，HBM bound 越绝对，异步搬运与 FP8 QK^T 的相对收益越大。</p>\n<p>判断一个请求是否落在配方内，工程上不看分辨率标签，看三个量：序列长度 N、head_dim、每 head 的 tile 形状。N 决定 IO 与计算的比值，head_dim 决定 tcgen05 MMA 的 K 维是否落在 FP8 的合法形状上，tile 形状决定 TMA 搬运粒度与双缓冲深度能否对齐。三者中任一不满足，kernel 要么回退到非异步路径，要么触发重写。公式给出的判据是直接的：</p>\n<div class=\"formula\">$$\\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}},\\qquad \\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</div>\n<p>第一式说明 IO 压力随 N² 增长、随 SRAM 容量反比下降；第二式说明加速比的上界就是 HBM 时间与 SM 时间的比值——当 SM 时间被 FP8 QK^T 压缩一半，而 HBM 时间不变，加速比才真正兑现。这就是为什么 16k 序列下能拿到 2–4 倍时延下降，而 2k 序列下这个数字不成立：SM bound 仍占主导，压缩 SM 时间只是把瓶颈挪了个位置。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-25\">二十五 · 长度分布：批内方差比均值更致命</h3>\n<p>连续批处理把不同请求拼进同一个 micro-batch，异步 FA3 的 tile 调度是按最长序列铺开的。若批内序列长度分布集中（例如同一分辨率档位的采样批次），Q tile 数量一致，KV 双缓冲的预取节奏整齐，warp-specialized 流水几乎没有空转；若分布长尾——一批里混着 4k 与 16k——短序列的 Q tile 很快耗尽，其 SM 让出来却无法被长序列的 KV 预取填满，因为 TMA 预取是按 tile 粒度发起的，跨请求的 tile 不能拼接。结果是批内 SM 利用率被最长请求钉死，吞吐按最长序列计价，短请求的算力被浪费。</p>\n<p>代价体现在两个指标上：一是有效吞吐，micro-batch 的 token 产出除以最长请求的时延，长尾分布下这个值会显著低于按平均长度估算的容量；二是显存，KV tile 双缓冲按最长序列的 tile 数预留 shared memory，短请求占着缓冲区却不产生重叠收益。工程上的处理不是把长短请求混批，而是按序列长度分桶：4k–8k 一桶、8k–16k 一桶，桶内 tile 数接近，TMA 预取与 MMA 的节拍一致。分桶的代价是调度器要多维护几条队列，收益是每个桶的流水都能跑满。</p>\n<p>具体例子：一个 16k 序列的请求在双缓冲深度为 2 时，KV tile 的预取必须严格领先当前 MMA 一个 tile；若同批混入一个 4k 请求，它的 Q tile 只够铺满流水的前段，后段的 KV 预取没有消费者，TMA 引擎空转，HBM 带宽被无效搬运占用——这正是“KV 双缓冲深度不足时预取与 MMA 无法重叠、HBM 流量回落”的另一种表现形式，只不过触发原因从深度不足换成了批内长度失配。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-26\">二十六 · 并发与批大小：occupancy 与 shared memory 的拉扯</h3>\n<p>异步 FA3 的并发能力受 shared memory 容量与双缓冲深度双重约束。每个 SM 上驻留的 KV tile 缓冲区大小 = tile 数 × tile 字节数 × 缓冲深度，这个量直接吃掉可用于并发 CTA 的 shared memory 预算。批大小增大时，若每个请求仍按最长序列预留缓冲，SM 上的 CTA 数被迫下降，occupancy 掉到无法掩盖 TMA 延迟的水平；批大小过小则 TMA 预取没有足够的独立请求流来填满 HBM 通道，带宽利用率不足。</p>\n<p>配方给出的边界是定性的：规模上限受 shared memory 容量与双缓冲深度约束。这意味着批大小的选择不是“越大越好”，而是在给定 tile 形状下求一个使 TMA 吞吐与 MMA 吞吐匹配的点。伪代码层面的判断可以写成：</p>\n<div class=\"formula\">$$\\text{occupancy}=\\frac{\\text{SMEM}_{\\text{per SM}}}{\\text{tile}_{KV}\\times\\text{depth}\\times\\text{CTA}_{\\text{per req}}},\\qquad \\text{util}=\\min\\!\\left(\\frac{\\text{TMA rate}}{\\text{MMA rate}},\\,1\\right)$$</div>\n<p>第一式说明并发 CTA 数与缓冲深度成反比，深度加一档，occupancy 就掉一档；第二式说明有效利用率由搬运速率与计算速率的较小者决定。工程判断是：先把深度定在能覆盖一次 TMA 往返延迟的最小值（通常是 2），再用批大小去填剩余的 shared memory，而不是反过来先定批大小再挤深度。深度被挤掉，16k 序列的时延收益直接被吃掉，因为预取与 MMA 不再重叠，HBM 流量回落到接近朴素 attention 的水平。</p>\n<p>具体例子：head_dim 为 128 的 DiT 变体，tile 取 128×128，FP8 下每 tile 的 KV 字节数固定；若把双缓冲改成单缓冲以腾出空间给更大批，表面上看并发上去了，但每次 MMA 前都要同步等 TMA 完成，warp-specialized 的生产者 warp 与消费者 warp 退化成串行，16k 序列下 2–4 倍的时延下降不复存在。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-27\">二十七 · 负载不对时的三种退化</h3>\n<p>第一类是精度退化。FP8 QK^T 对 attention logit 的动态范围敏感，per-head scaling 是配方的必要组件而非可选优化。当负载里出现 logit 幅值跨度大的 head（高分辨率细节区域与平坦区域共存时常见），缺少 per-head scaling 会让 FP8 的表示范围溢出，softmax 的指数项被截断，注意力权重分布失真，表现为高分辨率细节糊化。这种退化不可通过后处理挽回，因为信息在 QK^T 量化那一步就丢了。PV 保持 FP16 只能保住值聚合的精度，救不回已经失真的权重。</p>\n<p>第二类是形状退化。warp-specialized 流水对 head_dim 与 tile 形状挑剔，非 64/128 对齐的 DiT 变体直接套用 kernel 会触发重写或性能回退。对齐要求来自 tcgen05 MMA 的合法形状与 TMA 的搬运粒度：head_dim 不是 64 的倍数，QK^T 的 K 维切不整齐，MMA 指令要么走窄形状导致吞吐减半，要么需要 padding 搬运无效数据。此时流水无法按预期重叠，生产者与消费者 warp 的节拍错位，收益从 2–4 倍回落到与 FlashAttention-2 同档。</p>\n<p>第三类是带宽退化。KV 双缓冲深度不足时，TMA 预取与 MMA 无法重叠，HBM 流量回落。这一条在批大小被强行拉高、shared memory 被挤占时最容易触发。三种退化的共同特征是：症状出现在时延与画质上，根因却在负载配方与 kernel 形状约束的匹配上。定位时先查 per-head scaling 是否开启，再查 head_dim 与 tile 的对齐，最后查双缓冲深度与批大小的配比。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-28\">二十八 · 配方核对清单与工程判断</h3>\n<p>把上述约束收敛成一张可执行的核对表，按顺序过一遍即可判断一个负载是否落在异步 FA3 的配方内：</p>\n<table class=\"mini\"><thead><tr><th>核对项</th><th>配方要求</th><th>不满足时的退化</th></tr></thead><tbody>\n<tr><td>序列长度</td><td>4k–16k，1024² 以上分辨率</td><td>SM bound 主导，加速比不兑现</td></tr>\n<tr><td>head_dim / tile</td><td>64/128 对齐</td><td>kernel 重写或性能回退，流水不重叠</td></tr>\n<tr><td>per-head scaling</td><td>FP8 QK^T 必须开启</td><td>logit 溢出，高分辨率细节糊化</td></tr>\n<tr><td>双缓冲深度</td><td>≥2，覆盖一次 TMA 往返</td><td>预取与 MMA 串行，HBM 流量回落</td></tr>\n<tr><td>批内长度分布</td><td>按长度分桶，桶内 tile 数接近</td><td>SM 被最长请求钉死，吞吐按最长计价</td></tr>\n</tbody></table>\n<p>这张表里没有一项是“调参”，每一项都是负载形态与 kernel 结构的匹配问题。序列长度决定瓶颈归属，对齐决定流水能否成立，scaling 决定数值是否可信，深度决定重叠是否发生，分桶决定批内算力是否浪费。五项全过，16k 序列下 2–4 倍的时延下降才是可预期的；任一项不过，收益按该项的退化程度打折。</p>\n<p>工程判断落在最后一项上：当负载无法调整（例如业务侧就是长短混合的采样请求），正确的做法不是在 kernel 层硬扛，而是在调度层分桶，把长度方差从批内挪到批间。异步 FA3 的流水是为同构 tile 序列设计的，异构批只会让生产者/消费者的节拍失配；把同构性还给 kernel，收益才回得来。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-29\">二十九 · 负载配方与失效边界：异步 FA3 在什么请求形态下才划算</h3>\n<p>这套 warp-specialized 异步 FA3 的收益不是无条件成立的，它本质上是一个<strong>按序列长度换 HBM 流量</strong>的方案。收益来源可以写成一条粗略的比例关系：<div class=\"formula\">$$\\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}},\\quad \\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}}$$</div>当 $N$ 小、$d$ 小的时候，朴素 attention 的 HBM 读写量并不构成压倒性瓶颈，SM 侧反而有富余，此时把 QK^T 拆成 FP8 tcgen05 MMA、把 KV 用 TMA 双缓冲预取的复杂度全部变成纯开销——流水启动、tile 切分、跨 tile 的 online softmax 递推合并都要付固定成本，而分母上的 SM bound 并没有被抬高多少。所以负载配方第一条就是<strong>请求形态必须是 1024² 以上分辨率、序列长度落在 4k–16k 的 DiT 采样</strong>；低于这个区间，朴素 kernel 或常规 FlashAttention 变体的端到端时延反而更稳，异步 FA3 的 2–4 倍时延收益只在 16k 这类长序列上才兑现。批大小与 SLO 的具体数值未给出，但工程判断是：批内序列长度分布要<strong>尽量同质</strong>，长短混批会让 tile 循环次数由最长序列决定，短序列的 SM 在流水里空转。</p>\n<p>第二个失效条件是数值侧。<strong>FP8 QK^T 对 attention logit 的动态范围敏感</strong>，必须做 per-head scaling；一旦缺少这一层缩放，logit 溢出会让高分辨率细节糊化，而这种画质退化无法靠后处理挽回——它不是噪声，是注意力权重被系统性压扁后的结构性丢失。这与“PV 保持 FP16 使画质几乎无损”是两件事：PV 的高精度只保护了值聚合这一侧，QK^T 的量化误差直接决定 softmax 的尖锐程度，也就直接决定 1024² 以上纹理与边缘的还原度。因此负载配方里必须带一条<strong>精度准入</strong>：per-head scaling 的校准数据要覆盖目标分辨率区间的真实采样分布，而不是拿低分辨率校准结果外推。第三个失效条件是形状约束：warp-specialized 流水对 head_dim 与 tile 形状挑剔，<strong>非 64/128 对齐的 DiT 变体</strong>直接套用 kernel 会触发重写或性能回退，生产者/消费者无法按预期重叠，此时理论上的 2–4 倍收益直接归零，只剩维护成本。</p>\n<p>第四个、也是最容易被忽略的失效条件是<strong>双缓冲深度</strong>。KV tile 驻留 shared memory 做双缓冲，TMA 预取与 tcgen05 MMA 的重叠依赖“下一 tile 已在途”这一前提；当 shared memory 容量不足以容纳足够深的缓冲、或 tile 尺寸被迫放大到挤占缓冲槽位时，预取与计算退化为串行，HBM 流量回落到接近朴素 attention 的水平，16k 序列的时延收益被吃掉。规模上限因此受 shared memory 容量与双缓冲深度约束，而不是受 HBM 带宽约束——这是一个反直觉但很实际的边界。下表把负载形态与预期行为对齐，便于在容量规划阶段做准入判断：</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>流水重叠</th><th>主要代价</th><th>工程判断</th></tr></thead><tbody><tr><td>4k 以下、短序列为主</td><td>启动开销占比高</td><td>固定成本摊薄不足</td><td>不走此方案</td></tr><tr><td>4k–16k、长度同质</td><td>QK^T 与 PV 充分重叠</td><td>shared memory 占用</td><td>收益区间，16k 时延降 2–4 倍</td></tr><tr><td>长短混批</td><td>由最长序列决定循环</td><td>短序列 SM 空转</td><td>需按长度分桶调度</td></tr><tr><td>head_dim 非 64/128 对齐</td><td>无法按预期重叠</td><td>kernel 重写</td><td>先改形状再谈收益</td></tr><tr><td>双缓冲深度不足</td><td>预取与 MMA 串行</td><td>HBM 流量回落</td><td>收益被吃掉，需扩 shared memory 预算</td></tr></tbody></table>\n<p>把这几条合起来看，负载配方的实质是<strong>三个准入条件同时成立</strong>：序列长度在 4k–16k 且分布同质、head_dim 与 tile 按 64/128 对齐、shared memory 预算足以支撑双缓冲深度；再叠加 per-head scaling 的精度校准。任何一条不满足，方案不是“慢一点”，而是退化到与朴素 attention 同量级的 HBM 瓶颈上，同时还要付 warp-specialized 流水的调度复杂度。反过来，当这三条成立时，attention 的 HBM 流量从 $O(N^2)$ 降到 $O(N\\cdot d)$，输出写回 HBM 后直接喂给下一层 DiT block 的 LayerNorm，整条数据通路不需要额外的中转缓冲——这也是为什么负载不对时，损失的不只是这一层，而是整条 DiT block 链路的流水节奏。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-30\">三十 · 硬件档位：把 SM100 的异步通路吃满，而不是把卡堆多</h3>\n<p>部署这套异步 FA3 的第一个判断不是“买几张 B200”，而是“这张卡的异步通路有没有被喂满”。机制上，kernel 的性能取决于 TMA 预取 KV tile 的节奏能否与 tcgen05 MMA 的发射节奏对齐：TMA 把 KV tile 搬进 shared memory 双缓冲，QK^T 在 FP8 下走 tcgen05 MMA，softmax 在寄存器内做 online 归一化写回 FP32 累加器，softmax 结果转 FP16 后与 V tile 做 PV GEMM。整条链路上真正稀缺的资源是 shared memory 容量与双缓冲深度，而不是 FLOPs。硬件档位因此按“单卡能否容纳目标序列的 tile 流水”来分：SM100（B200/B300）单卡即可承载 4k–16k 序列的 Q tile 切分与 KV 双缓冲；GB200/GB300 NVL72 机柜档位的价值不在单卡算力，而在于把跨卡 KV 分片与集合通信压进 NVLink 5 域内，避免 HBM 往返。</p>\n<p>代价侧要算清楚：双缓冲深度不足时，TMA 预取与 MMA 无法重叠，HBM 流量回落到朴素 attention 的量级，16k 序列的 2–4 倍时延收益被直接吃掉。这是一个显存换带宽的交换——每加深一级 KV 双缓冲，就多占一份 shared memory，留给 Q tile 与 softmax 累加器的空间随之缩小。工程判断是：先按 head_dim 64/128 对齐确定 tile 形状，再反推双缓冲深度，最后才决定卡型；顺序颠倒会得到一台算力过剩但流水打不满的机器。</p>\n<div class=\"formula\">$$\\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}},\\quad \\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</div>\n<p>举例：一个 head_dim=128、序列 16k 的 DiT block，若 tile 取 128×128，KV 双缓冲每级占用的 shared memory 随 tile 与 head 数线性增长；当双缓冲只能放一级时，kernel 退化为“搬完再算”，此时即便 SM 利用率数字好看，端到端时延也不降。反过来，head_dim=96 这类非 64/128 对齐的变体，warp-specialized 流水无法按预期重叠，必须重写 kernel，硬件档位再高也无济于事。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-31\">三十一 · 并行拓扑：序列切分优先于张量切分</h3>\n<p>这套 kernel 的并行拓扑有一个硬约束：Q tile 是按序列切的，KV 以 tile 为单位被 TMA 预取，因此序列并行（SP）天然贴合数据流，而张量并行（TP）会切开 head 维度、让每个 rank 只持有部分 head 的 KV，反而增加跨 rank 的 KV 聚合。部署配方因此把序列切分放在第一层：长序列沿 N 维切成若干段，每段独立跑完整的 online softmax 递推，跨 tile 合并仍按 running max 与归一化因子的递推完成，最后统一除以归一化因子。TP 只在单卡放不下 head 数时启用，且必须保证切分后每个 rank 的 head_dim 仍是 64/128 对齐。</p>\n<p>机柜档位下，NVL72 的 NVLink 5 域让 KV 分片的跨卡搬运不必落 HBM，但通信代价依然存在：每层 DiT block 的 attention 输出要喂给下一层的 LayerNorm，若序列切分导致跨卡归约，则每层引入一次 all-reduce 级别的同步。工程上应尽量让序列切分的边界与 DiT block 边界对齐，把跨卡通信压缩到 block 之间而非 block 内部。代价是显存：序列切分不减少单卡 KV 占用，只减少单卡的 Q tile 工作量；真正的显存节省来自 KV 分片驻留，而这又依赖双缓冲深度与 shared memory 预算。</p>\n<ul>\n<li>第一层：序列并行，按 N 切段，段内完整跑 FA3 流水，跨段仅合并归一化因子。</li>\n<li>第二层：head 维 TP，仅在单卡 head 数放不下时启用，切分后保持 64/128 对齐。</li>\n<li>第三层：机柜内 KV 分片走 NVLink 5，避免 HBM 往返；跨机柜不切 attention。</li>\n</ul>\n<p>举例：16k 序列在单卡上按 4 段切分，每段 4k，段内 Q tile 与 KV 双缓冲的流水完全本地化；若改用 8 路 TP 切 head，每个 rank 的 KV tile 变小、TMA 预取粒度变细，双缓冲的搬运效率反而下降，且每层多出跨 rank 聚合。这就是“序列切分优先”的实证依据。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-32\">三十二 · 量化方案：FP8 只给 QK^T，PV 守 FP16，per-head scaling 是开关</h3>\n<p>量化方案在本 kernel 里不是全局开关，而是分段策略：QK^T 走 FP8 tcgen05 MMA 拿到吞吐翻倍，PV GEMM 保持 FP16 以守住画质。这个不对称的根源在于两条 GEMM 的数值敏感度不同——QK^T 产生的是 attention logit，进入 softmax 前只影响权重分布；PV 直接累加 value，误差会线性进入输出并逐层放大。因此部署配方把 FP8 限定在 QK^T，且必须配 per-head scaling：每个 head 独立统计 logit 动态范围并缩放，否则高分辨率细节糊化，且这种退化无法通过后处理挽回。</p>\n<p>代价是校准开销与 kernel 复杂度：per-head scaling 需要在运行时维护每 head 的缩放因子，若因子随层、随采样步漂移，则要周期性重估，这部分开销落在调度参数里而非 kernel 内部。另一个代价是数值路径的分裂——FP32 累加器、FP16 的 PV 输入、FP8 的 QK^T 输入共存，shared memory 里同时存在多种精度的 tile，双缓冲的排布必须按精度分区，否则 TMA 搬运的粒度与 MMA 的消费节奏对不上。</p>\n<div class=\"formula\">$$O_{i}=\\sum_{j}\\frac{\\exp(q_{i}k_{j}^{\\top}/\\sqrt{d}-m_{i})}{\\ell_{i}}v_{j}$$</div>\n<p>举例：一个 16k 序列、head_dim=128 的 DiT block，若 QK^T 用 FP8 但省略 per-head scaling，logit 动态范围溢出会让高频纹理的注意力权重被压平，1024² 以上分辨率的细节直接糊掉；加上 per-head scaling 后，FP8 吞吐翻倍而 PV 的 FP16 路径保证画质几乎无损。工程判断是：per-head scaling 不是可选优化，而是 FP8 QK^T 的准入条件。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-33\">三十三 · KV 策略：双缓冲深度决定收益上限</h3>\n<p>KV 策略的核心变量是双缓冲深度，它同时约束时延收益与显存占用。机制上，KV tile 以 TMA 异步预取到 shared memory，双缓冲让“搬下一 tile”与“算当前 tile”重叠；深度为 1 时重叠消失，HBM 流量回落到 O(N²) 量级，16k 序列的 2–4 倍时延收益被吃掉。深度为 2 是基线，深度继续加深则受 shared memory 容量约束——每多一级就挤占 Q tile 与 FP32 累加器的空间，最终触发 tile 形状缩小或 head 数切分，反而破坏 64/128 对齐。</p>\n<p>KV 驻留策略与序列长度挂钩：4k 序列下 KV 可以整段驻留 shared memory，流水退化为单次预取；16k 序列必须分 tile 流式预取，KV 无法整体驻留，这正是本 kernel 存在的理由。部署时按序列长度分档配置双缓冲深度：短序列用浅缓冲换更多 Q tile 并行，长序列用深缓冲换流水重叠。代价是显存带宽的占用峰值——TMA 预取与 PV GEMM 的 V tile 读取同时发生，HBM 带宽在 tile 边界处出现尖峰，调度参数需要为此留出余量。</p>\n<table class=\"mini\"><thead><tr><th>序列档位</th><th>KV 驻留方式</th><th>双缓冲深度取向</th><th>主要代价</th></tr></thead><tbody><tr><td>4k</td><td>整段可驻留</td><td>浅，换 Q tile 并行</td><td>shared memory 留给 Q tile</td></tr><tr><td>8k</td><td>分 tile 流式</td><td>基线两级</td><td>HBM 带宽尖峰</td></tr><tr><td>16k</td><td>必须流式，无法驻留</td><td>尽量加深，受容量约束</td><td>双缓冲不足则收益归零</td></tr></tbody></table>\n<p>举例：16k 序列若双缓冲只能放一级，TMA 预取与 MMA 串行，端到端时延与朴素 attention 无异；把深度提到两级后，QK^T 与 PV GEMM 的重叠恢复，时延收益回到 2–4 倍区间。这说明 KV 策略的调参顺序是“先保重叠，再谈深度”。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-34\">三十四 · 调度参数：按 tile 粒度而不是按请求粒度排队</h3>\n<p>调度层要匹配 kernel 的 tile 粒度。这套 FA3 的流水以 Q tile 为单位推进，跨 tile 合并靠 online softmax 递推，因此批调度若按整条请求排队，会让不同序列长度的请求互相等待，破坏 TMA 预取的连续性。部署配方把调度参数拆成三层：序列档位（4k/8k/16k）决定双缓冲深度与 tile 形状；head 对齐检查在准入阶段完成，非 64/128 对齐的变体直接路由到重写 kernel 的路径；per-head scaling 的重估周期挂在采样步边界上，避免在 tile 流水中间插入同步。</p>\n<p>连续批处理在这里的形态是“tile 级流水线填充”：当一个请求的 Q tile 在等 KV 预取时，另一个请求的 tile 可以占用 MMA 单元，前提是两者的 tile 形状与精度路径一致。代价是调度器的状态空间变大——每个在飞 tile 都携带 running max 与归一化因子，跨 tile 合并的中间状态要随 tile 一起调度，显存占用随在飞 tile 数线性增长。工程判断是：在飞 tile 数应受 shared memory 与双缓冲深度约束，而不是受请求队列长度约束。</p>\n<ul>\n<li>准入：检查 head_dim 与 tile 是否 64/128 对齐，不对齐则不走本 kernel。</li>\n<li>分档：按序列长度选双缓冲深度与 tile 形状，短序列不与长序列混排。</li>\n<li>重估：per-head scaling 在采样步边界刷新，不在 tile 流水中间插入。</li>\n<li>在飞：tile 数受 shared memory 预算约束，超出则排队而非加深缓冲。</li>\n</ul>\n<p>举例：一批混合 4k 与 16k 的 DiT 采样请求，若统一按 16k 档位配双缓冲，4k 请求的 Q tile 并行度被浪费；若按档位分队列，16k 请求的流水重叠得以保持，4k 请求走浅缓冲快路径，整体吞吐与时延同时改善。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-35\">三十五 · 可复现的配置思路：从对齐检查倒推</h3>\n<p>把上述五层串成一条可复现的配置路径，顺序是固定的：先做对齐检查，再定 tile 形状，再定双缓冲深度，再选并行拓扑，最后配量化与调度。对齐检查是硬门槛——head_dim 与 tile 非 64/128 对齐的 DiT 变体，warp-specialized 流水无法按预期重叠，直接套用 kernel 会触发重写或性能回退，这一步不通过就没有后续调参的意义。tile 形状确定后，双缓冲深度由 shared memory 预算反推：深度不足则 TMA 与 MMA 无法重叠，收益归零；深度足够则序列切分与 head 切分的拓扑才有意义。</p>\n<p>量化与调度是最后两层，因为它们依赖前面的形状决策：FP8 QK^T 的 per-head scaling 要在 tile 形状固定后才能确定缩放因子的粒度；调度参数要在双缓冲深度与在飞 tile 数确定后才能定队列策略。整条路径的代价是调参周期长——每一层都约束下一层，改一个 tile 形状会连锁改动双缓冲、拓扑与调度。工程判断是：把对齐检查与双缓冲深度做成启动时的断言，而不是运行时的自适应，因为这两项的失败模式（细节糊化、收益归零）在运行时难以观测，只能靠前置约束挡住。</p>\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n<p>举例：一个 head_dim=128、序列 16k 的 DiT 部署，启动断言检查 tile 128×128 对齐通过，shared memory 预算允许两级 KV 双缓冲，序列切 4 段走 SP、不启 TP，QK^T 开 FP8 并挂 per-head scaling，调度按 16k 档位单独排队。若把 head_dim 改成 96，断言失败，路由到重写 kernel 路径——这不是性能调优问题，而是流水结构不匹配的问题，任何调度参数都无法补偿。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-36\">三十六 · 这套配方的边界：对齐约束、双缓冲深度与画质退化</h3>\n<p>这套配方的收益不是无条件成立的，它被三条硬约束卡住：head_dim 与 tile 形状必须 64/128 对齐、shared memory 双缓冲深度必须足够、FP8 QK^T 必须带 per-head scaling。三者任一不满足，收益就从“16k 序列时延降 2–4 倍”回落到接近朴素 attention 的水平。对齐约束来自 warp-specialized 生产者/消费者流水本身：TMA 搬运的 tile 形状与 tcgen05 MMA 的操作数布局是绑定的，head_dim 非 64/128 对齐的 DiT 变体会让生产者与消费者无法按同一节奏推进，只能重写 kernel 或接受性能回退。双缓冲深度则由 shared memory 容量决定，KV tile 驻留不足时 TMA 预取与 MMA 无法重叠，HBM 流量回落，公式里的 $\\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$ 重新逼近 1。</p>\n<p>量化方案的代价集中在 QK^T 一侧。FP8 只用于 QK^T、PV 保持 FP16，画质几乎无损的前提是 attention logit 的动态范围被 per-head scaling 压进 FP8 可表示区间；缺少这一步，logit 溢出会让高分辨率细节糊化，且这种退化发生在采样过程中间层，后处理无法挽回。工程上应把 per-head scaling 当作 kernel 的必选参数而非可选优化，并在接入新 DiT 变体时先做单 head 的 logit 范围探测。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>直接后果</th><th>系统代价落点</th></tr></thead><tbody><tr><td>head_dim/tile 非 64/128 对齐</td><td>流水无法重叠，需重写 kernel</td><td>SM 利用率、时延</td></tr><tr><td>双缓冲深度不足</td><td>TMA 预取与 MMA 串行化</td><td>HBM 带宽、16k 时延收益</td></tr><tr><td>缺 per-head scaling</td><td>logit 溢出，细节糊化</td><td>画质，不可后处理修复</td></tr></tbody></table>\n<p>调度参数上，这套方案对批大小不敏感而对序列长度敏感：收益随 N 增长，4k 序列下 HBM 流量尚未完全压过 SM 计算，2–4 倍时延收益主要出现在 16k 端。因此容量规划应按分辨率分档配置，而不是用一套参数覆盖全部采样请求；高分辨率请求单独成批以维持 tile 形状一致，低分辨率请求走未量化的 QK^T 路径反而更稳。规模上限受 shared memory 容量与双缓冲深度约束，序列再长也不能靠加深缓冲解决，只能靠切分 Q tile 与跨 tile 的 online softmax 递推合并。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-37\">三十七 · 显存与驻留：双缓冲深度决定收益上限</h3>\n<p>异步 FA3 在 Blackwell 上的显存账要分三层算：HBM 里的 Q/K/V 与输出、shared memory 里的 KV tile 双缓冲、寄存器与 TMEM 里的 FP32 累加器与 running max/归一化因子。朴素 attention 在 16k 序列下 KV 无法驻留，只能反复回读 HBM；异步 FA3 把 KV tile 以 TMA 预取进 shared memory，用双缓冲让第 <em>t</em> 个 tile 的 MMA 与第 <em>t+1</em> 个 tile 的搬运重叠。问题在于 shared memory 容量是硬约束：每个 KV tile 占 <span>tile_N × head_dim × 元素宽度</span>，双缓冲意味着两份同时在场，再叠加 softmax 写回的 FP32 累加器与 FP16 的 P 矩阵，SM 上可用的 shared memory 很快被吃满。缓冲深度不足时，TMA 预取与 tcgen05 MMA 无法重叠，HBM 流量回落到接近朴素路径的水平，16k 序列那 2–4 倍的时延收益被直接吃掉——这是规模上去后第一个崩点，且崩得无声无息：kernel 不报错，只是 SM 利用率掉下去。</p>\n<p>代价可以用一个简单的占用关系表达。设每 SM 的 shared memory 预算为 <span>S</span>，单 tile 字节数为 <span>b</span>，双缓冲深度为 <span>D</span>，则并发 tile 数受 <span>⌊S/(D·b)⌋</span> 约束；当 <span>head_dim</span> 从 64 抬到 128，<span>b</span> 翻倍，若 <span>S</span> 不变则并发 tile 数减半，流水并行度随之下降。工程判断很直接：先按 head_dim 与 tile 形状反推 <span>D</span>，再决定 Q tile 的切分粒度；宁可切小 Q tile 换更深的 KV 双缓冲，也不要在 shared memory 上赌运气。批大小上升时，多个请求的 KV 争抢同一份 shared memory 预算，驻留策略必须从\"每请求独立双缓冲\"退化为\"按 tile 轮转复用\"，否则并发度被显存而非算力卡住。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-38\">三十八 · 带宽：O(N²) 到 O(N·d) 之后，瓶颈换了位置</h3>\n<p>异步 FA3 把 attention 的 HBM 流量从 O(N²) 降到 O(N·d)，但\"降下来\"不等于\"不再是瓶颈\"。16k 序列、head_dim 128 时，Q/K/V 与输出的基础流量仍随序列线性增长，而每层 DiT block 的输出要直接喂给下一层 LayerNorm，意味着 attention 的输出写回与下一层的读入在时间上紧邻，HBM 上形成写-读往返。此时真正的带宽压力来自三处：KV tile 的 TMA 预取带宽、P 矩阵从寄存器转 FP16 写回 shared memory 的片上带宽、以及跨 tile 合并时 FP32 累加器的读写。片上带宽（shared memory 与寄存器之间）在 Blackwell 上远高于 HBM，但 softmax 的 online 归一化每处理一个 tile 就要读写一次累加器，tile 数越多，片上往返越频繁。</p>\n<div class=\"formula\">$$\\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}},\\qquad \\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</div>\n<p>这个式子给出的是加速比的天花板：当 HBM bound 远大于 SM bound 时，异步流水才有意义；一旦序列长到 SM 侧的 softmax 与 MMA 成为主导，继续加深流水不再带来收益，反而因 tile 数增多抬高片上往返。规模上去后第二个崩点就在这里——不是 HBM 不够快，而是 softmax 的逐 tile 归一化把片上带宽吃满，SM 在等自己的寄存器。具体例子：16k 序列按 128 的 tile_N 切分有 128 个 KV tile，每个 tile 都要做一次 running max 更新与归一化因子重标定，累加器的读写次数与 tile 数成正比；把 tile_N 抬到 256 能把 tile 数减半、片上往返减半，代价是单 tile 的 shared memory 占用翻倍，又回到第一节的显存约束。两个约束互相拉扯，这就是调优的真实形状。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-39\">三十九 · 通信：并行切分与 KV 搬运的耦合</h3>\n<p>序列并行与张量并行在 attention 上的切分方式不同，通信代价也不同。序列并行把 N 维切开，每个 rank 持有部分 Q 与全部 KV 的对应分片，跨 tile 合并时的 online softmax 递推需要在 rank 间交换 running max 与归一化因子：<span>m</span> 与 <span>ℓ</span> 各一次 all-reduce，量级是 <span>O(rank × heads)</span>，本身不大，但它落在关键路径上——必须等所有 rank 的部分和到齐才能做最终归一化，于是 attention 的尾段被通信钉住。张量并行切 head 维，QK^T 与 PV 的 GEMM 在 head 内完成，通信发生在 attention 输出后的线性层，与 attention 本体解耦，关键路径更干净。工程上倾向在 attention 内部用 head 切分、在序列维用分块而非并行，把 all-reduce 推到 block 边界之外。</p>\n<p>KV 搬运在分离式预填/解码下变成跨节点通信。预填节点算出 KV 后要经 NVLink 5 与 NIXL 传到解码节点，16k 序列的 KV 体量随层数与 head 数线性放大，传输时间与 attention 计算时间在同一量级时，流水就被通信拖住。规模上去后第三个崩点：解码侧的 batch 增大，KV 传输带宽成为共享资源，多个请求的 KV 搬运互相排队，尾延迟抬升。缓解手段是把 KV 传输与解码的 attention 计算做流水重叠——传第 <em>i</em> 层的 KV 时算第 <em>i−1</em> 层，但这要求解码侧有足够的 shared memory 与 HBM 暂存来缓冲在途 KV，又回到显存预算。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-40\">四十 · 功耗与时钟：FP8 省下的不只是时间</h3>\n<p>FP8 QK^T 在 Blackwell 上吞吐翻倍，功耗侧的意义同样实在：tcgen05 MMA 在 FP8 下的每瓦吞吐高于 FP16，QK^T 这一半的 attention 计算功耗下降，而 PV 保持 FP16 使精度损失可控。但功耗不是均匀分布的：softmax 的 online 归一化是标量密集的逐元素操作，寄存器压力大、ILP 低，单位功耗的有效吞吐远低于 MMA；warp-specialized 流水把生产者（TMA 搬运）与消费者（MMA 与 softmax）分成不同 warp，生产者 warp 在等待时仍在耗电，形成\"空转功耗\"。规模上去后，SM 长时间处于流水半满状态，功耗不降而吞吐不升，能效比恶化。</p>\n<p>时钟侧的影响更隐蔽：持续高占用的 MMA 会把 GPU 推向功耗上限，触发降频，而 attention 的尾段（最终归一化与输出写回）对时钟敏感，降频直接放大尾延迟。工程判断是把 QK^T 的 FP8 收益兑现为\"同样的时延预算下更低的占用\"，而不是\"同样的占用下更短的时延\"——留出功耗余量给尾段，比把 MMA 拉满更稳。per-head scaling 在这里也有功耗含义：缺少 scaling 时 logit 动态范围溢出，softmax 的 exp 计算出现大量极端值，数值路径退化，画质糊化的同时计算路径也变长。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-41\">四十一 · 尾延迟：均值好看，P99 崩在合并点</h3>\n<p>异步 FA3 的时延分布不是平的。稳态下 TMA 预取与 MMA 重叠良好，单 tile 的处理时间由 MMA 主导；但跨 tile 合并点——running max 更新、归一化因子重标定、最终除以 <span>ℓ</span>——是串行段，无法与下一 tile 的 QK^T 重叠，因为下一 tile 的部分和要等当前 tile 的 <span>m</span> 与 <span>ℓ</span> 定下来才能递推。序列越长，合并点越多，串行段在总时延中的占比越高。批调度把多个请求拼进同一 batch 时，合并点的串行化被放大：不同请求的序列长度不一，短请求先到合并点却要等长请求的 tile 走完，尾延迟由 batch 内最长序列决定。</p>\n<p>具体例子：一个 batch 里混着 4k 与 16k 序列的请求，16k 请求的 tile 数是 4k 请求的四倍，合并点出现四次，短请求的完成时间被拖到接近长请求。连续批处理能缓解但不能消除——新请求进入时若恰好撞上长请求的合并点，仍要排队。规模上去后第四个崩点：batch 越大，尾延迟的长尾越厚，P99 与均值的差距拉大，SLO 按均值定容量就会在高峰被打穿。工程手段是给合并点做优先级调度，让短序列请求的合并点插队，代价是长序列请求的 tile 流水被打断，需要重新预取。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-42\">四十二 · 规模上去先崩在哪：按序列长度分段的判断</h3>\n<p>把四个崩点按序列长度排序，可以得到一条工程判断线。4k–8k 区间，shared memory 双缓冲深度是首要约束，head_dim 128 时单 tile 字节数大，<span>D</span> 被压到 2 以下，流水重叠率低，收益打折；此时应优先调 tile 形状而非加并行。8k–16k 区间，片上带宽与 softmax 串行段成为主导，tile 数增多使累加器往返频繁，合并点占比上升，尾延迟开始脱离均值；此时应把 tile_N 抬大以减少 tile 数，同时接受 shared memory 占用上升。16k 以上，KV 跨节点通信与解码侧 batch 的 KV 排队成为瓶颈，attention 本体的优化边际收益递减，容量规划要从算力转向带宽与显存。</p>\n<table class=\"mini\"><thead><tr><th>规模区间</th><th>先崩的资源</th><th>可观测信号</th><th>应对方向</th></tr></thead><tbody><tr><td>4k–8k</td><td>shared memory 双缓冲深度</td><td>SM 利用率随 head_dim 上升而下降</td><td>调 tile 形状，降 Q tile 粒度换深缓冲</td></tr><tr><td>8k–16k</td><td>片上带宽与 softmax 串行段</td><td>P99 与均值差距拉大</td><td>抬 tile_N 减 tile 数，合并点插队调度</td></tr><tr><td>16k 以上</td><td>KV 跨节点带宽与解码侧排队</td><td>通信时间与计算时间同量级</td><td>KV 传输与 attention 分层流水重叠</td></tr></tbody></table>\n<p>还有一个跨区间的约束不能忽略：head_dim 与 tile 形状非 64/128 对齐的 DiT 变体，warp-specialized 流水无法按预期重叠，性能回退到接近朴素路径，此时任何规模判断都失效——必须先重写 kernel 再谈调优。per-head scaling 缺失则是另一种失效：数值路径退化不体现在时延上，而体现在画质上，高分辨率细节糊化后无法通过后处理挽回，属于\"吞吐达标但结果不可用\"的隐性崩点。容量规划时应把这两条作为前置校验，而不是事后补救。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-43\">四十三 · 规模上去以后，先崩的是 shared memory 与流水深度</h3>\n<p>异步 FA3 在 DiT 上的收益不是线性的，它被三个硬约束夹住：shared memory 容量、双缓冲深度、以及 head_dim 与 tile 的 64/128 对齐。KV tile 必须整块驻留 SMEM 才能让 TMA 预取与 tcgen05 MMA 重叠，于是每 SM 可用 SMEM 就决定了单 tile 的 K/V 尺寸上限；双缓冲要求两份 tile 同时在场，等于把可用容量再砍一半。当序列从 4k 推到 16k，Q tile 数量线性增长而单 tile 尺寸不变，SMEM 压力看似不变，但跨 tile 的 online softmax 递推要求 FP32 累加器与 running max/归一化因子常驻寄存器，寄存器压力随 head 数上升，occupancy 下降，warp-specialized 的生产者/消费者配比被迫调整，重叠窗口变窄。此时系统代价从“算力受限”翻转为“驻留受限”：HBM 流量不再由 O(N·d) 的渐近式主导，而由 tile 边界处的部分和回写与重读主导。</p>\n<p>把这一点写成可判据的形式：设单 SM 可用 SMEM 为 S、单 tile K/V 字节数为 b、双缓冲深度为 D，则需满足 <span class=\"formula\">$$D\\cdot b \\le S,\\quad \\text{有效重叠率}\\ \\eta \\approx \\frac{T_{\\text{TMA}}}{T_{\\text{MMA}}+T_{\\text{softmax}}}$$</span> 当 D 被迫降到 1，η 趋近 0，TMA 预取与 MMA 串行化，16k 序列下原本 2–4 倍的时延收益被吃掉大半，退化成接近朴素 attention 的 HBM 带宽受限形态。这不是精度问题，是流水结构在容量约束下的失效。</p>\n<table class=\"mini\"><thead><tr><th>规模档位</th><th>主导瓶颈</th><th>系统代价落点</th></tr></thead><tbody><tr><td>4k 序列</td><td>MMA 吞吐</td><td>FP8 QK^T 吞吐翻倍直接兑现，尾延迟平稳</td></tr><tr><td>8k–16k</td><td>SMEM 容量与双缓冲深度</td><td>重叠率下降，HBM 流量回升，尾延迟拉长</td></tr><tr><td>非 64/128 对齐变体</td><td>kernel 重写</td><td>warp-specialized 流水无法按预期重叠，性能回退</td></tr></tbody></table>\n<p>通信与功耗在单卡 DiT 采样里不是首要项，但在 NVL72 级部署上会显形：若把 16k 序列的 attention 按 head 或序列切分到多卡，跨 tile 的 online softmax 合并需要交换 running max 与归一化因子，这部分 all-reduce 的字节数随切分数增长，而它发生在每个 attention 层的关键路径上，直接放大尾延迟——批内长尾请求的 P99 由最慢那一次跨卡合并决定。功耗侧，FP8 tcgen05 MMA 把 QK^T 的能效抬高，但 PV 保持 FP16 意味着 tensor core 在两种精度间切换，SM 的时钟与供电策略在混合精度流水下更难压到稳态，持续高 occupancy 的 warp-specialized kernel 会让单卡功耗贴近上限，机柜级供电余量反过来限制可并发的采样批大小。工程判断很直接：先测 D 能否维持 2，再谈 16k 的时延收益；D 掉到 1 时，重写 tile 形状或缩小 head 分组比调批大小更有效。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-44\">四十四 · 规模上去以后，先崩的是 shared memory 而不是 HBM</h3>\n<p>异步 FA3 在 DiT 全局注意力上的收益不是线性的，它有一个由片上资源决定的硬天花板。KV tile 双缓冲要求同一时刻在 shared memory 里驻留两份 tile，加上 Q tile、FP32 累加器和 softmax 中间量，占用随 head_dim 与 tile 边长平方增长；一旦双缓冲深度被迫从 2 降到 1，TMA 预取就无法与 tcgen05 MMA 重叠，HBM 流量立刻回落到接近朴素 attention 的水平，16k 序列那 2–4 倍的时延收益被整段吃掉。这正是公式里 $\\text{Speedup}\\approx\\text{HBM bound}/\\text{SM bound}$ 的含义：加速比的上限由两条界的比值封顶，而双缓冲失效等于把分子重新抬高。工程判断很直接——先算 shared memory 预算再定 tile，而不是先定 tile 再祈祷能塞下。</p>\n<p>第二个先崩的点是尾延迟而非平均吞吐。DiT 采样是整图同步推进的，序列长度 4k–16k 且各 step 的 attention 形状固定，因此批内不存在长短请求的自然错峰；一旦某个 batch 的 tile 数不能被 SM 数整除，最后一批 wave 只跑到部分 SM，其余 SM 空转等这一 wave 收尾。序列越长，单 wave 的执行时间越长，这个“除不尽”的尾巴在端到端时延里的占比就越高。缓解手段是把 Q tile 切得更细以提高 wave 粒度，但这又反过来加重 shared memory 压力与每 tile 的固定开销，两者是对冲的。规模上去后，调度器看到的不是吞吐曲线变缓，而是 p99 时延出现台阶。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先触及的约束</th><th>系统表现</th></tr></thead><tbody><tr><td>序列 4k → 16k</td><td>shared memory 双缓冲深度</td><td>重叠失效，HBM 流量回升</td></tr><tr><td>batch 增大</td><td>SM wave 整除性</td><td>尾延迟台阶，p99 抬升</td></tr><tr><td>head_dim 非 64/128 对齐</td><td>kernel 形状假设</td><td>需重写或性能回退</td></tr></tbody></table>\n<p>通信与功耗在单卡内不是主矛盾，但在 NVL72 机架级部署上会显形。跨 SM 的 tile 不需要通信，可一旦 DiT block 因显存不足被切到多卡、attention 输出要经 NVLink 5 汇入下一层 LayerNorm，O(N·d) 的输出写回就从片上问题变成链路问题：序列越长，每 step 搬的激活越多，链路占用与功耗随分辨率同步上升。功耗侧的约束更隐蔽——FP8 QK^T 把 MMA 吞吐翻倍的同时把功耗密度推高，双缓冲满载时 SM 长期处于高占用，机架功率上限可能先于算力上限成为限制 batch 的因素。真正的失效顺序是：shared memory 容量 → wave 整除性 → 链路带宽 → 机架功率，逐级暴露，且每一级都比上一级更难通过改 kernel 参数绕开。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-45\">四十五 · 精度退化：FP8 QK^T 的溢出路径与可观测信号</h3>\n<p>异步 FA3 在 Blackwell 上的精度失败几乎不来自 PV 路径——PV 保持 FP16，误差量级与朴素 attention 同阶。真正的风险集中在 QK^T 的 FP8 段：logit 的动态范围由 per-head scaling 压缩到 e4m3 可表示区间，一旦某个 head 的 $q\\cdot k^\\top$ 分布尾部超出缩放后的上限，exp 之前的 logit 被截断，softmax 权重分布被压平，注意力从“尖峰选择”退化为“均匀混合”，在 DiT 上表现为高分辨率纹理细节糊化，且这种退化发生在采样轨迹内部，后处理无法挽回。</p>\n<p>诊断要从 online softmax 的中间量入手。递推式为</p>\n<div class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</div>\n<p>其中 $m$ 是 running max、$\\ell$ 是归一化因子。若 FP8 截断发生，$\\tilde m_i$ 会被系统性低估，导致 $\\ell_i$ 相对参考实现偏大，最终输出 $O_i$ 的范数偏小、方向被多 head 平均化。工程上不必逐元素比对，只需在 kernel 内挂两个轻量探针：每 head 每 tile 记录 $\\tilde m_i$ 与缩放上限的比值（饱和率），以及 $\\ell_i$ 与 FP32 参考路径的偏差（归一化漂移）。饱和率超过阈值即说明该 head 的 scale 选小了；归一化漂移单调上升则说明截断已在累积。</p>\n<p>代价方面，这两个探针只增加寄存器内的比较与一次原子累加，不引入额外 HBM 流量，对 16k 序列下 2–4 倍的时延收益几乎无损；但若为了诊断而回退到 FP32 QK^T，tcgen05 MMA 吞吐减半，SM bound 重新压过 HBM bound，收益直接归零。例子：某 DiT 变体在 2048² 输出上出现天空区域带状色块，探针显示第 3、7、11 号 head 饱和率在采样后段陡升——对应高分辨率 token 的 key 范数随去噪步数增长，固定 scale 不再适配，改为按步重估 per-head scale 后色块消失。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-46\">四十六 · 形状不匹配：非 64/128 对齐的静默回退</h3>\n<p>warp-specialized 生产者/消费者流水对 tile 形状的挑剔不是性能偏好，而是正确性前提：TMA 搬运的 KV tile 必须落在 shared memory 的 swizzle 布局上，MMA 的 fragment 划分要求 head_dim 为 64 或 128 的整数倍。当 DiT 变体的 head_dim 落在 96、80 这类值上，常见结局不是崩溃而是静默回退——框架回落到通用 kernel，双缓冲流水失效，TMA 预取与 MMA 不再重叠。</p>\n<p>这种回退在监控上表现为一个特征组合：SM 利用率下降、HBM 读带宽上升、单步时延上升，但错误率为零、输出数值正常。运维侧若只看端到端成功率，会把这类退化误判为“负载波动”。判定方法是把 attention 段的实际耗时与按 $O(N\\cdot d)$ 流量估算的理论下界对比，比值持续高于阈值即说明流水未生效。用公式表达，理论加速比</p>\n<div class=\"formula\">$$\\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</div>\n<p>在流水失效时退化为 1 附近，因为 HBM 流量回落到 $O(N^2)$ 量级而 SM 又在等数据。代价是显性的：16k 序列上原本 2–4 倍的时延收益被吃掉，且因为 shared memory 双缓冲仍按原 tile 尺寸分配，占用不降反升，挤占同 SM 上其他 kernel 的空间。</p>\n<p>处理策略分两层。编译期在 kernel 选择处做显式断言：head_dim 与 tile 形状不满足 64/128 对齐时直接报错而非回退，把问题暴露在部署前。运行期对已上线变体保留一个对齐检查探针，读取实际启动的 kernel 标识并与预期比对。例子：一个 head_dim=96 的 DiT 分支在灰度环境里端到端 P99 只上升了有限幅度，被误认为正常抖动；直到把 attention 段耗时单独打点，才发现流水从未生效，重写为 128 对齐的 padding 版本后恢复重叠。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-47\">四十七 · OOM 与批抖动：双缓冲深度与 KV 驻留的耦合</h3>\n<p>异步 FA3 的显存账本与传统 attention 不同：KV tile 驻留 shared memory 双缓冲，深度不足则 TMA 预取与 MMA 无法重叠，HBM 流量回落；深度足够则每 SM 的 shared memory 被吃满，留给并发 CTA 的空间收窄。当批调度器在同一 SM 上叠加多个请求的 attention 段，shared memory 需求按批内并发数线性增长，OOM 往往不在请求准入时发生，而在某个批恰好凑齐高分辨率样本的瞬间爆发。</p>\n<p>批抖动的机制是反馈环：一次 OOM 触发批缩小，缩小后单批的 attention tile 数减少、流水启动开销占比上升、单步时延变长；调度器为追平 SLO 又扩大批，再次撞上显存墙。表现为吞吐在两级之间来回跳，P99 时延呈锯齿。诊断要看两个量的相关性：批大小时间序列与 shared memory 峰值占用时间序列。若二者同步爬升并在同一时刻触顶，说明瓶颈是双缓冲深度而非 HBM 容量。</p>\n<p>缓解不靠调低批上限，而靠把双缓冲深度做成序列长度的函数：4k 序列用浅缓冲换并发，16k 序列用深缓冲保重叠，并在准入处按 $N$ 分档预留 shared memory。代价是调度器需要感知序列长度分布，准入逻辑变复杂；收益是消除锯齿，让 16k 样本的时延收益稳定兑现。例子：混合 4k 与 16k 请求的采样服务在统一批上限下反复 OOM，改为按序列长度分档预留后，OOM 消失且高分辨率档的 P99 收敛。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-48\">四十八 · 路由不均与尾延迟尖刺</h3>\n<p>分离式部署下，预填与解码节点各自跑 attention 段，请求按序列长度与当前队列深度路由。异步 FA3 的耗时对序列长度高度非线性——4k 到 16k 之间，tile 数增长四倍而流水启动开销摊薄，单位 token 成本反而下降。若路由器按“最短队列”而非“预计完成时间”决策，会把长序列请求集中投给恰好空闲但 shared memory 已被短序列占满的节点，造成该节点上长序列被迫使用浅缓冲、流水失效、单请求时延尖刺。</p>\n<p>尾延迟尖刺的另一个来源是 head 级不均衡：per-head scaling 使各 head 的饱和风险不同，饱和 head 触发重估 scale 时需要一次同步，该同步在 warp-specialized 流水里表现为生产者等待消费者清空累加器，整条流水停顿一个 tile 周期。单次停顿微小，但若多个 head 在同一批内相继触发，停顿叠加成可观测的尖刺。</p>\n<p>监控应把 P99 拆到“序列长度档 × 节点”的二维格子里，而不是全局聚合——全局 P99 会被大量短序列稀释，掩盖长序列档的尖刺。判定路由不均的信号是：同一序列长度档内，节点间 P99 方差显著大于节点内方差。处理上把路由打分改为预计完成时间，并对饱和 head 的重估做批内合并，把多次同步压成一次。代价是路由器需要维护每节点的在途工作量估计，状态同步带来额外控制面开销；收益是尾延迟从尖刺变为平滑的长尾。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-49\">四十九 · 监控分层与回滚判据</h3>\n<p>监控分三层，每层对应一类失败模式。数值层：per-head 饱和率、归一化漂移、输出范数相对参考路径的偏差，采样频率跟随去噪步而非请求，因为精度退化在步内累积。流水层：attention 段实测耗时与 $O(N\\cdot d)$ 理论下界的比值、TMA 预取与 MMA 的重叠率、实际启动 kernel 标识，用于捕获静默回退。资源层：shared memory 峰值占用与批大小的相关性、OOM 事件按序列长度档的分布，用于区分双缓冲深度不足与真实容量不足。</p>\n<p>回滚判据要可执行而非原则性。触发回滚的条件应写成组合：数值层饱和率越限且归一化漂移单调上升，同时流水层重叠率下降——三者同现说明不是偶发采样噪声，而是 scale 与形状的配置性错误。单一指标越限只触发告警与降级（如临时切回 FP16 QK^T），不触发全量回滚，因为 FP16 回退会让吞吐减半，代价高于局部精度损失。</p>\n<p>回滚路径本身要预置：保留上一版 kernel 的二进制与对应 per-head scale 表，回滚时连同 scale 一起切换，避免只换 kernel 而 scale 仍按新配置计算造成二次退化。例子：一次灰度中数值层告警单独出现，运维按判据只做了 FP16 降级，未全量回滚；后续确认是某 head 的 scale 表在变体合并时被覆盖，修正 scale 表后恢复 FP8 路径，全程未中断服务。</p>\n<p>工程判断落在最后一步：异步 FA3 的失败大多不是崩溃而是“性能与画质的静默退化”，因此监控的重心应从错误率转向“流水是否真的在重叠”与“logit 是否真的在表示范围内”这两个二值判断。把这两个判断做成 kernel 内的常驻探针、把它们的组合写成回滚判据，比任何端到端指标都更早暴露问题。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-50\">五十 · 失效边界：从数值溢出到流水塌陷的四种可观测病灶</h3>\n\n<p>这套异步 FA3 的收益并非无条件成立，它的失效模式几乎都沿着同一条因果链展开：<strong>数值动态范围 → tile 形状对齐 → 双缓冲深度 → 流水重叠率</strong>。第一类也是最隐蔽的是精度病灶。FP8 QK^T 的 logit 动态范围在没有 per-head scaling 时会溢出，表现为高分辨率细节糊化——注意这不是随机噪声，而是 attention 权重被压平后的结构性信息损失，后处理无法挽回。诊断上不能只看 loss 或 PSNR 全局指标，要在每个 head 上采样 logit 的 max/mean 比值：当某 head 的 $m_i$ 在跨 tile 递推中频繁被刷新，说明该 head 的 logit 分布尾部过重，per-head scale 需要按 $s_h=\\max|qk^\\top|/\\text{FP8}_{max}$ 单独标定。工程代价是每 head 一次额外的归约与一次 scale 广播，相对 16k 序列下 2–4 倍的时延收益可以忽略，但漏掉它的代价是整批采样画质不可用。</p>\n\n<p>第二类是形状病灶。warp-specialized 生产者/消费者流水对 head_dim 与 tile 形状挑剔，非 64/128 对齐的 DiT 变体直接套 kernel 会触发重写或性能回退——此时流水无法按预期重叠，SM 利用率掉回朴素 attention 的水平。监控手段是统计每个 kernel launch 的 MMA 占用率与 TMA 事务数之比：正常重叠时该比值稳定，一旦 tile 被 padding 到非对齐尺寸，TMA 搬运的有效字节占比下降，比值出现台阶式下跌。第三类是显存病灶，KV 双缓冲深度不足时 TMA 预取与 MMA 无法重叠，HBM 流量回落到接近 $O(N^2)$ 的量级，16k 序列的时延收益被直接吃掉。判据很直接：若 shared memory 只能容纳单缓冲，则 $\\text{IO}\\propto N^2d/\\text{SRAM}$ 中的 SRAM 项退化为常数搬运，速度上限 $\\text{Speedup}\\approx\\text{HBM bound}/\\text{SM bound}$ 趋近于 1。这类问题在扩容 batch 时最易暴露——批抖动本质是双缓冲被更多并发序列挤占后的预取饥饿。</p>\n\n<table class=\"mini\"><thead><tr><th>病灶</th><th>可观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>FP8 logit 溢出</td><td>per-head max/mean 比值尖峰、细节糊化</td><td>画质不可逆退化</td><td>补 per-head scaling，回滚到 FP16 QK^T</td></tr><tr><td>tile 非对齐</td><td>MMA/TMA 比值台阶下跌</td><td>重叠失效，吞吐回退</td><td>重写 kernel 或改 tile 形状</td></tr><tr><td>双缓冲不足</td><td>预取等待计数上升、批抖动</td><td>HBM 流量回升，时延收益归零</td><td>降 batch 或减 tile 尺寸</td></tr><tr><td>路由不均</td><td>尾延迟尖刺、单 SM 长尾</td><td>SLO 违约集中在 p99</td><td>按序列长度分桶调度</td></tr></tbody></table>\n\n<p>第四类是调度病灶，表现为尾延迟尖刺与路由不均。序列长度在 4k–16k 间波动时，同一 batch 内长短序列混排会让短序列等长序列的 tile 循环走完，p99 被最长序列钉死；这在连续批处理下尤其明显，因为新请求不断插入却无法抢占已在流水中的 tile 链。诊断要按序列长度分桶看 p50/p99 的分离度，若分离度随 batch 增大而扩大，就是路由不均而非 kernel 本身的问题。回滚策略应分级：精度类问题直接切回 FP16 QK^T（吞吐减半但画质恢复），形状类问题走 kernel 重写而非运行时开关，缓冲与调度类问题优先降 batch 与分桶，把 16k 长序列单独成批以保住 2–4 倍时延收益的主体部分。监控的最小集合是 per-head logit 统计、MMA/TMA 比值、预取等待计数与分桶尾延迟四项，缺一项就会在某一类病灶上失明。</p>\n<h3 id=\"alg-fa3-blackwell-attn-sec-51\">五十一 · 同族谱系：异步 FA3 在注意力实现树上的位置</h3>\n<p>把 Blackwell 上的注意力实现按“谁承担 HBM 流量、谁承担 SM 计算”两个轴切开，会得到一条清晰的谱系。最左端是朴素 attention：QK^T 与 softmax 全部物化，HBM 读写正比于 N²，SM 大部分时间在等数据。往右是 FlashAttention-2 式分块：tile 化后把中间矩阵留在 SRAM，HBM 流量降到 O(N·d)，但流水是同步的——softmax 与下一 tile 的 GEMM 之间靠 barrier 串行，Blackwell 的 TMA 异步通路基本闲置。再往右才是本片段的异步 FA3：warp-specialized 生产者/消费者把 TMA 预取、tcgen05 MMA、寄存器内 online softmax 拆到不同 warp 组，QK^T 走 FP8、PV 保持 FP16，三者在时间上重叠。谱系最右端是“近似替代”分支：线性注意力、稀疏/滑窗注意力、特征缓存跳步，它们不优化单次 attention 的 IO，而是直接削减 N 或跳过计算。</p>\n<p>选型的第一个判断不是“哪个 kernel 快”，而是“你的瓶颈落在哪一段”。用 <span class=\"formula\">$$\\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</span> 做粗判：当 N 在 4k–16k、d 为 64/128 时，朴素实现的 HBM bound 远大于 SM bound，异步 FA3 的收益上限就是这两者之比；当 N 已经压到 1k 以下，HBM bound 与 SM bound 接近，异步流水的重叠收益被摊薄，反而要付 warp 特化的调度开销。这就是为什么同一套 kernel 在低分辨率 DiT 上跑不出收益——不是 kernel 退化，是公式里的分子已经不够大。</p>\n<p>具体例子：一个 1024² 潜空间、patch 化后序列 4k 的 DiT block，若 head_dim 恰为 64，异步 FA3 可直接套用，收益落在“时延降 2–4 倍”区间的下沿；同一模型换到 16k 序列，收益走到上沿。反过来，一个 head_dim 为 96 的变体，warp-specialized 流水对 tile 形状挑剔，非 64/128 对齐会触发重写 kernel，此时应先评估“重写成本 vs 收益”，而不是硬套。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-52\">五十二 · 与 FlashAttention-2 的分界：异步通路是否被真正用起来</h3>\n<p>FA2 与异步 FA3 的算法骨架相同——都是 tile 化 + online softmax 递推，跨 tile 合并用 <span class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</span>。差别全在“谁在等谁”。FA2 的循环体是：加载 KV tile → 算 QK^T → softmax → 算 PV → 下一 tile，每一步之间是隐式同步，TMA 的异步拷贝即便发出，也没有独立的消费者 warp 去接。异步 FA3 把这套循环拆成生产者（发 TMA、管双缓冲）与消费者（MMA + softmax），让第 i 个 tile 的 PV GEMM 与第 i+1 个 tile 的 QK^T 在时间上叠起来。</p>\n<p>因此分界线不是“FA3 比 FA2 新”，而是“你的硬件是否有可被利用的异步搬运通路，且你的 tile 形状是否让双缓冲有意义”。在 Blackwell 上，TMA + tcgen05 的组合让这条通路成立；若把同一 kernel 搬到没有对应异步能力的档位，warp 特化只剩调度开销。工程判断可以写成一条伪代码式的准入条件：</p>\n<div class=\"formula\">$$\\text{useAsyncFA3} = (\\text{arch}\\ge\\text{Blackwell}) \\wedge (N\\ge 4\\text{k}) \\wedge (\\text{head\\_dim}\\in\\{64,128\\}) \\wedge (\\text{SMEM\\_tiles}\\ge 2)$$</div>\n<p>代价侧要盯住 shared memory：双缓冲深度不足时，TMA 预取与 MMA 无法重叠，HBM 流量回落，16k 序列的时延收益被吃掉——这正是失败模式里最隐蔽的一条，因为 kernel 不报错，只是慢。显存账也算得清：KV tile 驻留 shared memory 而非 HBM，省下的是 KV 的重复读写带宽，不是 KV 的绝对占用；后者仍由批大小与序列长度决定。</p>\n<p>例子：同一 16k 序列的 DiT 采样，FA2 路径下 SM 利用率被同步点压住，HBM 读写仍是主瓶颈；切到异步 FA3 后，QK^T 的 FP8 吞吐翻倍与 PV 的 FP16 精度并存，画质几乎无损。这个组合是“精度分层”的典型：只把对动态范围最敏感之外的环节降精度。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-53\">五十三 · 与近似替代分支的分界：削减 N 还是优化 IO</h3>\n<p>线性注意力、滑窗/稀疏注意力、特征缓存与块级跳步，走的是另一条路：它们改变 N 的有效规模或跳过整块计算，从而把 <span class=\"formula\">$$\\text{IO}\\propto \\frac{N^{2}d}{\\text{SRAM}}$$</span> 里的 N 直接压小。异步 FA3 不碰 N，只把常数因子里的 HBM 项换成 SRAM 项。两者不互斥，但优先级不同。</p>\n<p>判断规则：若你的画质/一致性指标对全局感受野敏感——高分辨率细节、跨区域结构一致性——削减 N 会引入可见退化，此时应先用异步 FA3 把 IO 打下来，再考虑近似。若序列已到 16k 且 SLO 极紧，单靠 IO 优化不够，才叠加滑窗或特征缓存。代价侧：近似分支省的是计算量与显存，但会改变数值分布，校准与回归测试成本高；异步 FA3 省的是带宽，数值上只引入 FP8 QK^T 的量化误差，且可用 per-head scaling 压住。</p>\n<p>例子：一个 16k 序列的 DiT 采样，若直接上滑窗注意力，跨窗的长程依赖丢失，高分辨率细节糊化；若先上异步 FA3，HBM 流量从 O(N²) 降到 O(N·d)，时延降 2–4 倍，画质几乎无损，此时再评估是否还需要滑窗。顺序反了，就会用画质换本来可以靠带宽优化拿到的时延。</p>\n<table class=\"mini\"><thead><tr><th>对照维度</th><th>异步 FA3</th><th>FA2 式分块</th><th>近似替代（滑窗/线性/缓存）</th></tr></thead><tbody><tr><td>优化对象</td><td>HBM→SRAM 流量与流水重叠</td><td>中间矩阵物化</td><td>有效 N 或跳过计算</td></tr><tr><td>数值影响</td><td>FP8 QK^T 量化误差，PV 保持 FP16</td><td>基本无</td><td>改变感受野，分布偏移</td></tr><tr><td>形状约束</td><td>head_dim/tile 需 64/128 对齐</td><td>较宽松</td><td>与形状弱相关</td></tr><tr><td>主要代价</td><td>SMEM 双缓冲深度、kernel 重写</td><td>同步点导致的 SM 空转</td><td>画质回归与校准成本</td></tr></tbody></table>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-54\">五十四 · 与精度分层族的分界：FP8 注意力 vs 全链量化</h3>\n<p>同族里还有一条精度线：DiT FP8 注意力与 GEMM、NVFP4 混合精度、分块 PTQ 校准。它们与本片段的交集在“QK^T 用 FP8”这一点上，但范围不同。异步 FA3 是“局部精度分层”：只把 QK^T 降到 FP8，softmax 在寄存器内做 online 归一化并写回 FP32 累加器，PV 转 FP16 与 V tile 相乘——精度损失被限制在 logit 计算这一段，且由 per-head scaling 兜住动态范围。全链 FP8/NVFP4 则把权重、激活、甚至 PV 都压到低精度，收益更大但校准面更宽。</p>\n<p>选型判断：若你的画质回归预算只允许“几乎无损”，选异步 FA3 的局部方案；若显存与带宽是硬约束、且愿意为校准投入工程，才走全链量化。两者可以叠加，但叠加时要注意 per-head scaling 与全链 scale 的交互——两套 scaling 各自独立推导会在 logit 上产生不一致的偏置。代价侧：FP8 QK^T 缺少 per-head scaling 时，attention logit 动态范围溢出会导致高分辨率细节糊化，且这种退化难以通过后处理挽回；这是本族里唯一“错了就不可逆”的失败模式。</p>\n<p>例子：一个 4k 序列的 DiT block，若已决定全链 NVFP4，则注意力段的 FP8 QK^T 收益被上游量化的误差掩盖，此时异步 FA3 的价值主要落在流水重叠而非精度分层；反过来，若上游仍是 FP16，异步 FA3 的 FP8 QK^T 是性价比最高的一刀。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-55\">五十五 · 决策表：按序列长度、形状对齐与 SLO 三轴选型</h3>\n<p>把上面的分界收成一张可执行的表。三轴是：N（4k 以下 / 4k–16k / 16k 以上）、形状（head_dim 与 tile 是否 64/128 对齐）、SLO（时延紧不紧）。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>首选</th><th>次选</th><th>不建议</th></tr></thead><tbody><tr><td>N&lt;4k，形状对齐</td><td>FA2 式分块或朴素 tile 化</td><td>异步 FA3（收益摊薄）</td><td>近似替代（画质代价不划算）</td></tr><tr><td>N 4k–16k，64/128 对齐，SLO 紧</td><td>异步 FA3（FP8 QK^T + FP16 PV）</td><td>异步 FA3 + 特征缓存</td><td>FA2（SM 空转）</td></tr><tr><td>N 4k–16k，形状非对齐</td><td>先评估 kernel 重写成本</td><td>FA2 式分块过渡</td><td>硬套异步 FA3（性能回退）</td></tr><tr><td>N&gt;16k，SLO 极紧</td><td>异步 FA3 + 滑窗/稀疏</td><td>异步 FA3 + 块级跳步</td><td>纯近似（长程依赖丢失）</td></tr><tr><td>显存硬约束</td><td>全链 FP8/NVFP4 + 异步 FA3</td><td>异步 FA3 局部精度分层</td><td>仅靠异步 FA3 省显存（它省带宽不省占用）</td></tr></tbody></table>\n<p>表里每一格的“不建议”都有对应的系统代价：N&lt;4k 时异步 FA3 的 warp 特化调度开销压过重叠收益；形状非对齐时重写 kernel 的工程成本可能高于收益；纯近似在 16k 以上会以画质换时延，而时延本可靠带宽优化拿到。显存那一行要特别注意：异步 FA3 把 KV tile 驻留 shared memory，减少的是重复读写的带宽，KV 的绝对占用仍随批大小与 N 线性增长，规模上限受 shared memory 容量与双缓冲深度约束。</p>\n<p>例子：一个 16k 序列、head_dim 128、SLO 要求单步采样在预算内的 DiT 服务，表里落在第二行——异步 FA3 直上，per-head scaling 必开，双缓冲至少两级；若实测发现 SMEM 深度不足导致 TMA 与 MMA 不重叠，先加深缓冲而不是换算法，因为换算法会把已经拿到的 2–4 倍收益丢掉。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-56\">五十六 · 适用条件的硬边界与工程判断</h3>\n<p>硬边界有三条，越界就不是调参问题而是重写问题。第一条是形状：head_dim 与 tile 需 64/128 对齐，非对齐的 DiT 变体直接套用 kernel 会触发重写或性能回退，warp-specialized 流水无法按预期重叠。第二条是 SMEM 容量：双缓冲深度决定 TMA 预取能否与 MMA 重叠，深度不足时 HBM 流量回落，16k 序列的时延收益被吃掉。第三条是数值：FP8 QK^T 必须配 per-head scaling，否则 logit 动态范围溢出，高分辨率细节糊化且不可后处理挽回。</p>\n<p>工程判断可以写成一条决策顺序：先算 <span class=\"formula\">$$\\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</span> 确认收益上限是否值得投入；再查形状对齐，不对齐就先估重写成本；再查 SMEM 预算能否撑起双缓冲；最后才决定是否叠加近似分支或全链量化。这个顺序不能颠倒——先上近似再回头优化 IO，等于用画质买了本可免费拿到的带宽收益。</p>\n<p>具体机制上，跨 tile 合并的递推式 <span class=\"formula\">$$m_i=\\max(m_{i-1},\\tilde m_i),\\quad \\ell_i=e^{m_{i-1}-m_i}\\ell_{i-1}+e^{\\tilde m_i-m_i}\\tilde\\ell_i$$</span> 是选型时最容易被忽略的一环：它决定了 FP32 累加器的寄存器压力，而寄存器压力又反过来约束 tile 大小与双缓冲深度。换句话说，公式里的 m 与 ℓ 不只是数值稳定性的技巧，它们是 SMEM/寄存器预算的隐形约束项——当你在决策表里选“异步 FA3 + 滑窗”时，滑窗缩小了单 tile 的有效 KV 范围，反而给了双缓冲更多深度余量，这是叠加近似分支时少见的正收益，但只在 N 远大于 16k 时才值得考虑。</p>\n<p>最后一个判断落在“收益随序列长度增长”这条曲线上：4k 时收益在下沿，16k 时在上沿，中间是连续过渡。若你的服务同时承载 4k 与 16k 两类请求，按请求形态分流到不同 kernel 比强行统一更划算——4k 走 FA2 式分块避免特化开销，16k 走异步 FA3 吃满重叠收益，分流的路由成本远低于让 4k 请求陪跑 16k 的 kernel 配置。</p>\n\n<h3 id=\"alg-fa3-blackwell-attn-sec-57\">五十七 · 边界在哪：与 FA2、朴素分块、PagedAttention 的选型对照</h3>\n<p>这套异步 FA3 的收益不是无条件成立的，它换取的加速比可以写成 <span class=\"formula\">$$\\text{Speedup}\\approx\\frac{\\text{HBM bound}}{\\text{SM bound}}$$</span>，只有当朴素实现的耗时确实被 HBM 读写主导时，把 QK^T 与 softmax 重叠才有意义。因此选型的第一道判据是序列长度与算术强度：4k 以下、或 head_dim 很小导致每 tile 计算量不足的 DiT 变体，HBM bound 与 SM bound 差距不大，warp-specialized 流水带来的调度开销反而可能吃掉收益。第二道判据是形状对齐——head_dim 与 tile 必须落在 64/128 上，非对齐变体要么重写 kernel，要么退回 FlashAttention-2 式流水（其流水未针对 Blackwell 异步通路优化，TMA 与 tcgen05 的潜力释放不出来）。第三道是精度预算：若画质容错极低、连 per-head scaling 都不愿引入，则应保留全 FP16 的 QK^T，此时吞吐翻倍的好处让位于数值稳定。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody><tr><td>朴素全局注意力</td><td>序列短、调试期基线</td><td>HBM 流量 O(N²)，SM 空转</td></tr><tr><td>FlashAttention-2 流水</td><td>head_dim 非 64/128 对齐、移植成本敏感</td><td>未用 TMA 异步通路，Blackwell 上留性能</td></tr><tr><td>本方案（异步 FA3）</td><td>4k–16k、形状对齐、可做 per-head scaling</td><td>shared memory 容量与双缓冲深度受限</td></tr><tr><td>PagedAttention 类</td><td>KV 跨请求复用、变长批</td><td>分页寻址开销，长序列单请求收益有限</td></tr></tbody></table>\n<p>失效条件要盯住三处。其一，FP8 QK^T 缺 per-head scaling 时 logit 动态范围溢出，高分辨率细节糊化且后处理无法挽回——这是精度侧的一票否决项，不是调参能绕过的。其二，KV 双缓冲深度不足时 TMA 预取与 MMA 无法重叠，HBM 流量回落到接近朴素水平，16k 序列那 2–4 倍时延收益被直接吃掉；双缓冲深度受 shared memory 容量约束，这同时是规模上限。其三，tile 形状与 head_dim 非对齐会触发 kernel 重写或性能回退，工程上应把对齐检查放进模型编译期而非运行期。</p>\n<p>工程判断上，把这条路径当作“长序列 DiT 的默认档”而非“通用档”：先用序列长度 4k 作为分水岭筛掉短序列请求，再用 head_dim/tile 对齐筛掉异构变体，剩下的流量才交给异步 FA3 与 FP8 QK^T + FP16 PV 的组合。对不满足条件的请求保留 FA2 或全 FP16 回退路径，比强行改写 kernel 更划算——回退路径的吞吐损失是线性的，而重写 kernel 的代价是一次性的工期与后续维护。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · DiT 低比特量化与数值格式</td></tr><tr><td>解决什么</td><td>DiT 的全局注意力在 1024² 以上分辨率时序列长度 4k–16k，朴素 attention 的 HBM 读写成为…</td></tr><tr><td>一句话机制</td><td>用 FlashAttention-3 的 warp-specialized 生产者/消费者流水，把 QK^T 的 GE…</td></tr><tr><td>代价与失效</td><td>FP8 QK^T 对 attention logit 动态范围敏感，需 per-head scaling，否则高分辨率细节糊；warp-s…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-fa3-blackwell-attn · 共 8 个片段</p>\n";break;}}})();
